  libdata[libdataItem++] = new Array("./red__fitscube_extensions.html#red::fitscube_extensions", "red::fitscube_extensions", 'routine in <a href="./red__fitscube_extensions.html">red__fitscube_extensions.pro</a>', "red__fitscube_extensions.pro", "    Mats Löfdahl   ", "red::fitscube_extensions", " Add extensions to a fits file.   ", "wcs_time_coordinatewcs_wave_coordinatescannumberfilename       The name of the file.   ", "SST pipeline", "    2016-03-24 : MGL. First version.   ");
  
  

libdata[libdataItem++] = new Array("./red__fitscube_finalize.html", "red__fitscube_finalize.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__fitscube_finalize.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__fitscube_finalize.html#red::fitscube_finalize", "red::fitscube_finalize", 'routine in <a href="./red__fitscube_finalize.html">red__fitscube_finalize.pro</a>', "red__fitscube_finalize.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red::fitscube_finalize", " Correct various mistakes in the fitscube header, that have been made  during the development of the pipeline. Set the SOLARNET compliance  status to 1.   Do it also to the spectral cube, if there is one.   ", "do_spectral_file      Do process the spectral version of the input file (if there is       one). This should not be needed as crispex uses only the main       HDU data, and detects if it is different than in the regular       file.   header      The new header.   helpkeywords      Keywords and values to be added to the header. Keywords are       upcased and checked against a list of SOLARNET-approved       keywords.   no_checksum      Do not calculate DATASUM and CHECKSUM.   no_wbcubeno_write      Don't write the new header(s) (and don't compute checksums).       Combine this with keywords header, old_header, spectral_header,       and old_spectral_header to check what changes would be done.   old_header      The old header.   old_spectral_header      The old header of the spectral file.   old_wb_headerrelease_comment      The value of the RELEASEC keyword, a comment with details about       the proprietary state of the data, and whom to contact.   release_date      The value of the RELEASE keyword, a date after which the data       are not proprietary.   spectral_header      The new header of the spectral file.   wb_headerfeature      The value of FEATURE keyword, names of solar features in the FOV.   observer      The value of the OBSERVER keyword, names of observers.   silentpoint_id      The value of POINT_ID keyword, typically date and timestamp,       sometimes with '_mosaic' or '_grouped' endings.   filename      The path of the fitscube file.   ", "SST pipeline", "   2019-06-12 : MGL. First version.     2019-06-17 : MGL. New keyword help.     2019-06-18 : MGL. New keywords smooth_width and outfile. Add                 prstep header info.     2019-07-04 : MGL. Optionally (opt-out) add checksum and datasum.     2019-10-18 : MGL. New keywords svo_api_key and svo_username.     2020-07-06 : MGL. Split from red::fitscube_export.     2020-07-13 : MGL. New keywords no_write, header, old_header,                 spectral_header, old_spectral_header.     2020-07-15 : MGL. Remove keyword no_spectral_file, add keyword                 do_spectral_file.     2020-07-15 : MGL. Recursively finalize also the matching WB cube.     2022-03-08 : OA. New keywords feature, observer, point_id     2022-04-05 : OA. Moved part of the code to 'red__fitscube_header_finalize'.   ");
  
  

libdata[libdataItem++] = new Array("./red__fitscube_finish.html", "red__fitscube_finish.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__fitscube_finish.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__fitscube_finish.html#red::fitscube_finish", "red::fitscube_finish", 'routine in <a href="./red__fitscube_finish.html">red__fitscube_finish.pro</a>', "red__fitscube_finish.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red::fitscube_finish", " Close the fitscube file, optionally make a  flipped  version.   ", "direction      The direction parameter, that is normally equal to       self.direction but can be set explicitly to a different value       by the user of the calling method.   flipfile      The precense of this keyword causes a  flipped  version of the       [Nx, Ny, Ntuning, Nstokes, Nscans] fitscube to be produced, in       which the dimensions are [Ntuning, Nstokes, Nscans, Nx, Ny].       The name of the flipped file is returned in the keyword.   wcs      WCS info to be written as a binary extension.   lun      The logical unit number of the fitscube file to finish.   ", "SST pipeline", "   2017-09-11 : MGL. First version.     2017-11-16 : MGL. Now works with integer cubes.     2020-05-04 : MGL. New keyword direction.    ");
  
  

