  libdata[libdataItem++] = new Array("./red__fitscube_header_finalize.html#red::fitscube_header_finalize", "red::fitscube_header_finalize", 'routine in <a href="./red__fitscube_header_finalize.html">red__fitscube_header_finalize.pro</a>', "red__fitscube_header_finalize.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red::fitscube_header_finalize", " Correct various mistakes in the fitscube header, that have been made  during the development of the pipeline. Set the SOLARNET compliance  status to 1.   ", "keywords      Keywords and values to be added to the header. Keywords are       upcased and checked against a list of SOLARNET-approved       keywords.   no_checksum      Do not calculate DATASUM and CHECKSUM.   coordinatesrelease_date      The value of the RELEASE keyword, a date after which the data       are not proprietary.   release_comment      The value of the RELEASEC keyword, a comment with details about       the proprietary state of the data, and whom to contact.   featureobserverpoint_idsilentstatushdr      Fitscube header.   ", "SST pipeline", "   2022-04-05 : OA. Imported the code from 'red__fitscube_finalize'.   ");
  
  

libdata[libdataItem++] = new Array("./red__fitscube_initialize.html", "red__fitscube_initialize.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__fitscube_initialize.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__fitscube_initialize.html#red::fitscube_initialize", "red::fitscube_initialize", 'routine in <a href="./red__fitscube_initialize.html">red__fitscube_initialize.pro</a>', "red__fitscube_initialize.pro", "    Mats Löfdahl   ", "red::fitscube_initialize", " Create a fits file to write data cube slices into when you don't  want to have the entire cube in memory at the same time.   ", "wcsfilename       The name of the file to create.   hdr       The complete fits header of the file. The NAXIS* and BITPIX        keywords are used to set the file up.   lun       The logical unit of the opened file.   fileassoc       An assoc variable that can be used to write (and read!) data        slices.   dimensions       The dimensions of the data cube.   ", "SST pipeline", "    2016-03-24 : MGL. First version.      2017-06-05 : MGL. Remove WCS keywords.      2017-09-07 : MGL. Changed red_fitsaddpar --&gt; red_fitsaddkeyword.      2017-10-06 : MGL. Headers for tabulating spatial coordinates.      2017-10-18 : MGL. Move adding of WCS related file header keywords                  to fitscube_addwcs method.   ");
  
  

libdata[libdataItem++] = new Array("./red__fitscube_integer.html", "red__fitscube_integer.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__fitscube_integer.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__fitscube_integer.html#red::fitscube_integer", "red::fitscube_integer", 'routine in <a href="./red__fitscube_integer.html">red__fitscube_integer.pro</a>', "red__fitscube_integer.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red::fitscube_integer", " Make an integer version of a floating point fitscube.   ", "delete       Delete the input file if this keyword is set.   flip       Produce a flipped version if this keyword is set.   outname       The name of the output file.   overwrite       Don't care if the output cube is already on disk, overwrite it        with a new version.   fname       The name of the input file.   ", "SST pipeline", "   2018-11-02 : MGL. First version.   ");
  
  

libdata[libdataItem++] = new Array("./red__fitscube_intensitycorr.html", "red__fitscube_intensitycorr.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__fitscube_intensitycorr.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__fitscube_intensitycorr.html#red::fitscube_intensitycorr", "red::fitscube_intensitycorr", 'routine in <a href="./red__fitscube_intensitycorr.html">red__fitscube_intensitycorr.pro</a>', "red__fitscube_intensitycorr.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red::fitscube_intensitycorr", " Correct a fitscube for intensity variation between observation time  and prefilter calibration time.   ", "fitpref_timeintensitycorrmethod       One of 'old' (for correction based on comparing the current        scan with the prefilter calibration data), or 'fit' (for        correction based on comparing intensity from        fit_wb_diskcenter, evaluated at the current time and at the        time of the prefilter calibration). Boolean value TRUE is        equivalent to 'fit'. FALSE and 'none' (really any string value        that is not 'fit' or 'old') results in no correction. (The        values  fit_wb  and  fit_nb  are also permitted, the former        useful to select the WB fit when a NB fit is present.)   notimecheckfilename       The name of the file containing the fitscube.   ", "SST pipeline", "   2019-08-26 : MGL. First version.     2019-10-10 : MGL. New keyword nodiskcenter.     2020-01-22 : MGL. Remove keyword nodiskcenter, new keyword                 corrmethod.     2020-10-28 : MGL. Remove statistics calculations.     2021-10-19 : MGL. Use NB intensity fit for correction if                 available.     2025-10-09 : MGL. New keyword notimecheck.   ");
  
  

libdata[libdataItem++] = new Array("./red__fitscube_mask.html", "red__fitscube_mask.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__fitscube_mask.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__fitscube_mask.html#red::fitscube_mask", "red::fitscube_mask", 'routine in <a href="./red__fitscube_mask.html">red__fitscube_mask.pro</a>', "red__fitscube_mask.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red::fitscube_mask", " Define and apply a mask on the FOV of a fitscube and then crop to fit.   ", "ituning      The tuning index of the Stokes image displayed when defining       the mask. If not given, the core tuning will be used.   noflip      If set, don't make any spectral,  flipped  data cubes.   no_qhull      Instead of computing the mask from the convex hull of several       ROIs, just use the union of the ROIs.   include_I      If set, use mask also for stokes I and crop NB and WB cubes.   no_crop      If set, don't crop the FOV.   no_wb_maskmask      FOV mask to be reused with other cubes (particularly WB cube).   nomissing_nansoverwrite      Overwrite an existing file.   tag      If not overwriting the original file, add this tag to the       original filename.   infile      The path to the input fitscube.   ", "SST pipeline", "    2025-11-11 . MGL. First version.      2026-03-24 . OA. Added keywords, 'no_crop', 'include_I', 'mask'.                      Added recursive call for WB cube.   ");
  
  

libdata[libdataItem++] = new Array("./red__fitscube_missing.html", "red__fitscube_missing.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__fitscube_missing.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__fitscube_missing.html#red::fitscube_missing", "red::fitscube_missing", 'routine in <a href="./red__fitscube_missing.html">red__fitscube_missing.pro</a>', "red__fitscube_missing.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red::fitscube_missing", " Set pixels with missing data to NaN or median(frame) in a fitscube  file.   ", "force     Do it again if it's already done.   missing_type     What value to set missing-data pixels to. One of 'nan' and      'median' (of each frame). By default, set it to the opposite of      what it appears to be in the input cube.   noflip     Don't make a flipped version.   oname     The path of the output file.   overwrite     If oname is given and is an existing file, don't      overwrite unless this keyword is set.   filename     The path of the file.   ", "SST pipeline", "    2020-06-29 : MGL. First version.      2020-10-28 : MGL. Remove statistics calculations.    ");
  
  

libdata[libdataItem++] = new Array("./red__fitscube_nup.html", "red__fitscube_nup.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__fitscube_nup.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__fitscube_nup.html#red::fitscube_nup", "red::fitscube_nup", 'routine in <a href="./red__fitscube_nup.html">red__fitscube_nup.pro</a>', "red__fitscube_nup.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red::fitscube_nup", " Fix the orientation and rotation of old fitscubes.   This is for fitscubes made before we implemented the rotation and  orientation setup parameters and with the average derotation angle  subtracted. The goal is to produce a cube that is oriented along  HPLN/HPLT coordinate axes with N up as they normally are done.   The direction and orientation parameters, whether from config.txt or  given as keywords, are used to determine how the cube *should* be  rotated. The mirrorx and mirrory keywords on the other hand, or if  they are missing possibly info from a momfbd config file, are used  to determine how it is *currently* oriented.   ", "direction      The relative orientation of reference cameras of different       instruments. Note that only if direction is set in the config       file will it be assumed to be correct when setting the CSYERR       FITS header keyword.   wcdirectionrotation      Offset angle to be added to the field rotation angles.   flipdo_wb_cube      Set to correct WB cube as well.   wcs_improve_spatial      Set to align FOV of a fitscube with HMI intensity image.       Use when there are prominent features in FOV.   mirrorx      The cube wb data are mirrored in the X direction compared to       the raw data.   mirrory      The cube wb data are mirrored in the Y direction compared to       the raw data.   outdiroutname      Where to write the output. A spectral cube might also be       written, the file name for this will be generated based on       outname. If a variable, will be returned with the actual file       name.   overwrite       Don't care if cube is already on disk, overwrite it        with a new version.   no_checksum      Do not calculate DATASUM and CHECKSUM.   release_date      The value of the RELEASE keyword, a date after which the data       are not proprietary.   release_comment      The value of the RELEASEC keyword, a comment with details about       the proprietary state of the data, and whom to contact.   feature      The value of FEATURE keyword, names of solar features in the FOV.   observer      The value of the OBSERVER keyword, names of observers.   point_id      Value for the POINT_ID header keyword.   nthreadsstatusinname       The path to the file to be converted.   ", "SST pipeline", "    2022-03-29 : MGL. First version.      2022-04-11 : OA. Added recursive call for wb cube, keywords for                  finalizing the header, time-dependent solar                  coordinates in WCS.   ");
  
  

