libdata[libdataItem++] = new Array("./red__imagescale.html", "red__imagescale.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__imagescale.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__imagescale.html#red::imagescale", "red::imagescale", 'routine in <a href="./red__imagescale.html">red__imagescale.pro</a>', "red__imagescale.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red::imagescale", " Calculate the image scale based on pinhole grid pitch measurements.   The CRISP image scale depends on the prefilter for some years. If no  measurements exist, just use the default from the config file.   Try to get a value, using these sources in order: 1.  self.image_scales (from raw pinholes, written in config file), 2.  measurements from file (by the pinhole alignment step), 3. measure  from summed pinholes, 4. self.image_scale. The first 3 are  individual measurments for different prefilters. The last one is  common to all prefilters.   ", "no_gridfile     Do not use the pre-measured gridhole pitch values.   use_config     Use the image scales from the config file, self.image_scale or      self.image_scales, and not those measured for this day.   use_measurementverbose     Write messages about what we are doing.   pref     The prefilter for which to calculate the image scale.   ", "SST pipeline", "   2024-06-17 : MGL. First version.      The image plate scale in arcsec per pixel.   ");
  
  

