  libdata[libdataItem++] = new Array("./red__inverse_modmatrices.html#red::inverse_modmatrices", "red::inverse_modmatrices", 'routine in <a href="./red__inverse_modmatrices.html">red__inverse_modmatrices.pro</a>', "red__inverse_modmatrices.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red::inverse_modmatrices", " Read inverse modulation matrix maps from disk, make and store them  if necessary.   This method does (or at least is meant to do) the same as  red__polarim.pro in the master (old CRISP) branch, except that it  stores the inverse modulation matrices to disk rather than pointing  to them from within the pol class object. (We don't use a pol class  in the new code base.)   ", "camrcamtimmrimmtno_ccdtabsoverwriteprefilterdir", "SST pipeline", "   2018-10-09 : MGL. First version, based on Jaime's red::polarim.     2018-12-21 : MGL. Removed keyword smooth.     2019-05-29: MGL. Use the cache to avoid reading the inverse                modulation matrices over and over.     2022-09-10: MGL. CRISP --&gt; RED.   ");
  
  

