  libdata[libdataItem++] = new Array("./red__make_intdif_gains.html#red::make_intdif_gains", "red::make_intdif_gains", 'routine in <a href="./red__make_intdif_gains.html">red__make_intdif_gains.pro</a>', "red__make_intdif_gains.pro", "    Jaime de la Cruz Rodriguez, ISP   ", "red::make_intdif_gains", " Make time-dependent gainfiles.   ", "allbadcam debug maxminmosaic_tagoverwritepref preservepsfw   all : in, optional, type=boolean        Process all data sets.     mosaic_tag : in, optional, type=string        Filename tag that identifies different tiles in data collected       in automatic mosaic mode.     overwrite : in, optional, type=boolean        Overwrite existing gainfiles.     tdirs : in, optional, type=strarr        Process datasets with tdirs timestamps   scan smallscalesmoothsumlc tdirstimeaver", "CRISP pipeline", "   2013-07-01 : JdlCR. Created!     2013-12-17 : PS. Make smallscale default. If SUMLC is given, don't                 recompute the gain and use links     2015-05-07 : MGL. With a *, run all directories.     2016-02-17 : MGL. New keyword  all .     2017-04-26 : MGL. Use rdx_cbezier3.     2018-09-19 : MGL. Adapt to new codebase.     2019-03-28 : MGL. Make gains with /preserve for prefilters with                 backscatter correction, i.e., 8542 and 7772.     2021-07-06 : OA. Add tdirs keyword.     2019-03-28 : MGL. New keyword overwrite. Default is now not to                 overwrite existing gainfiles.     2022-11-15 : MGL. New keyword mosaic_tag.   ");
  
  

