libdata[libdataItem++] = new Array("./red__make_scan_cube.html", "red__make_scan_cube.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__make_scan_cube.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__make_scan_cube.html#red::make_scan_cube", "red::make_scan_cube", 'routine in <a href="./red__make_scan_cube.html">red__make_scan_cube.pro</a>', "red__make_scan_cube.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red::make_scan_cube", " Make FITS data cubes with momfbd-restored narrowband images, one  scan per file.   ", "autocrop      Try to determine the largest FOV that avoids any bad momfbd       subfields along the edges. If this keyword is set, the input       value of the crop keyword is ignored and is set to the       auto-detected crop parameters.   circular_fov       Do not make room for corners of the FOV in derotation.   clips       Used to compute stretch vectors for the wideband alignment.   cmap_fwhm       FWHM in pixels of kernel used for smoothing the cavity map.   crop       The array given here will be used to limit the FOV to        [xl+crop[0],xh-crop[1],yl+[crop[3],yh-crop[3]]. If /autocrop,        then the auto detected crop is returned in this keyword        instead.   direction       The relative orientation of reference cameras of different        instruments.   filenamefitpref_timeinteger       Store as integers instead of floats.   intensitycorrmethod       Indicate whether to do intensity correction based on WB data        and with what method. See documentation for red::fitscube_intensitycorr.   interactive       Set this keyword to define the data cube FOV by use of the        XROI GUI. If autocrop is set, then use the so defined FOV as        an initialization of the FOV in the GUI. Otherwise use the        crop keyword (or its default).   limb_data       Set for data where the limb is in the FOV. Disables autocrop.   mosaicnocavitymap       Do not add cavity maps to the WCS metadata.   nocrosstalk       Do not correct the (polarimetric) data cube Stokes components        for crosstalk from I to Q, U, V.   no_intensitycorr_timechecknomissing_nansnopolarimetrynorotation       Do not apply the direction parameter.   nthreadsodir       The output directory.   overwrite       Don't care if cube is already on disk, overwrite it        with a new version.   padmargin       Amount of rotation padding in pixels.   redemodulate       Delete any old (per scan-and-tuning) stokes cubes so they will        have to be demodulated from scratch.   rotationscannos       Choose scan numbers to include in the sequence by entering a        comma-and-dash delimited string, like '2-5,7-20,22-30' or the        string '*' to include all.   tiles       Used to compute stretch vectors for the wideband alignment.   tuning_selection       The index or indices in the tuning dimension to use for        calculating the polarimetric crosstalk correction. Should        correspond to continuum (or as close to continuum as        possible), where the polarimetric signal is minimal. Negative        indices are allowed.   dir       The directory where the momfbd output is stored.   ", "SST pipeline", "    2019-03-21 : MGL. First crisp version, based on the chromis one                  and code from crisp::make_nb_cube.      2019-08-26 : MGL. Do integerization, statistics calculations, and                  WB intensity correction by calling subprograms.      2020-01-16 : MGL. New keywords intensitycorrmethod and odir.      2020-04-01 : MGL. New keywords direction and norotation.      2020-04-27 : MGL. New keyword rotation.      2020-07-15 : MGL. Remove keyword smooth.      2020-10-28 : MGL. Remove statistics calculations.      2020-12-15 : JdlCR. There is one element missing in dummy ff                  vector. /norotation keyword was not implemented                  properly. The cropping info was not applied to the                  output image.      2022-06-24 : JdlCR. Bugfix, the cmap was always rotated                  regardless of the /norotation keyword.      2022-09-04 : MGL. CRISP --&gt; RED. New keyword circular_fov.      2025-02-20 : MGL. Adapt to new camera alignment model.      2025-10-09 : MGL. New keyword no_intensitycorr_timecheck.   ");
  
  

libdata[libdataItem++] = new Array("./red__make_stokes_cubes.html", "red__make_stokes_cubes.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__make_stokes_cubes.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__make_stokes_cubes.html#red::make_stokes_cubes", "red::make_stokes_cubes", 'routine in <a href="./red__make_stokes_cubes.html">red__make_stokes_cubes.pro</a>', "red__make_stokes_cubes.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red::make_stokes_cubes", " Make Stokes cubes by demodulating momfbd output files.   ", "clips       Used to compute stretch vectors for the wideband alignment.   cmap_fwhm       FWHM in pixels of kernel used for smoothing the cavity map.   nocavitymap       Do not add cavity maps to the WCS metadata.   overwrite       Don't care if cube is already on disk, overwrite it        with a new version.   noremove_periodic       Do not attempt to use Fourier filtering to remove polcal        periodic artifacts. (See crisp::demodulate method.)   notelmatredemodulate       Delete any old (per scan-and-tuning) stokes cubes so they will        have to be demodulated from scratch.   snamesstokesdirtiles       Used to compute stretch vectors for the wideband alignment.   nthreads       number of threads to use in red_stretch   nearest       perform nearest neighbor interpolation (default = bilinear)   fitpref_timedir       The path to the momfbd-restored data.   scanno       The scan number for which to make Stokes cubes.   ", "SST pipeline", "    2019-03-21 : MGL. First version.      2020-07-15 : MGL. Remove keyword smooth.      2020-10-01 : JdlCR. Use the new stretching routines and allow for                  optional nearest neighbor interpolation.      2022-09-10 : MGL. CRISP --&gt; RED.      2025-02-20 : MGL. Adapt to new camera alignment model.    ");
  
  

