  libdata[libdataItem++] = new Array("./red__makegains.html#red::makegains", "red::makegains", 'routine in <a href="./red__makegains.html">red__makegains.pro</a>', "red__makegains.pro", " ", "red::makegains", " ", "bad cam files       Flat files to make gains out of.   flatminmax min nthreads pref smoothsize ", "CHROMIS pipeline", "   2013-06-04 : Split from monolithic version of crispred.pro.     2013-08-27 : MGL. Added support for logging. Let the subprogram                 find out its own name.     2016-02-15 : MGL. Use loadbackscatter. Remove keyword descatter,                 new keyword no_descatter.     2017-04-06 : MGL. Make version for CHROMIS without backscatter or                 zeroing of detector tap borders.     2017-12-20 : MGL. Store gains with metadata headers.     2018-04-19 : MGL. Rewrote using filenames() method, separate                 ordinary flats and cavity-free flats.     2018-08-21 : MGL. New keyword files.     2022-08-29 : MGL. CHROMIS --&gt; RED.     2024-11-02 : JdlCR. Modifications for new                 demodulation/flat-fielding scheme.     2025-08-10 : MGL. New keyword flatmin.   ");
  
  

