  libdata[libdataItem++] = new Array("./red__match_prefilters.html#red::match_prefilters", "red::match_prefilters", 'routine in <a href="./red__match_prefilters.html">red__match_prefilters.pro</a>', "red__match_prefilters.pro", "    Mats Löfdahl, ISP   ", "red::match_prefilters", " Check if two lists of wideband and narrowband prefilters belong to  matching scans.   ", "pf1       A list of prefilters, wb or nb.   pf2       A list of prefilters, wb or nb.   ", "SST pipeline", "    2020-05-28 : MGL. Allow different lengths if one of them is 1.       An array of booleans.   ");
  
  

