  libdata[libdataItem++] = new Array("./red__polcalcube.html#red::polcalcube", "red::polcalcube", 'routine in <a href="./red__polcalcube.html">red__polcalcube.pro</a>', "red__polcalcube.pro", " ", "red::polcalcube", " ", "cam pref no_descatter      Don't do back-scatter compensation.   nthreads no_polcal_flatfieldingforce_polcal_flatfielding", "CRISP pipeline", "   2013-06-04 : Split from monolithic version of crispred.pro.     2013-08-27 : MGL. Added support for logging. Let the subprogram                 find out its own name.     2016-02-15 : MGL. Use loadbackscatter. Remove keyword descatter,                 new keyword no_descatter.     2018-02-02 : MGL. Adapt to new codebase.     2018-04-16 : MGL. Write single FITS files with extensions.     2024-11-21 : JdlCR. Implemented flatfielding of the modulation                 matrix for alternative demodulation done through. To                 revert to old behaviour use /no_polcal_flatfielding.   ");
  
  

