  libdata[libdataItem++] = new Array("./red__prepmomfbd_fitsheaders.html#red::prepmomfbd_fitsheaders", "red::prepmomfbd_fitsheaders", 'routine in <a href="./red__prepmomfbd_fitsheaders.html">red__prepmomfbd_fitsheaders.pro</a>', "red__prepmomfbd_fitsheaders.pro", "    Mats Löfdahl, ISP   ", "red::prepmomfbd_fitsheaders", " Write FITS header files for expected MOMFBD output.   ", "dirs       The data  timestamp  directories to process.   cfg_tag       A short string to be added to the  cfg  part of the path.   momfbddir       Top directory of output tree.   mosaicno_narrowbandpref       Prefilter.   scannono_pd       Set this to exclude phase diversity data and processing.   ", "SST pipeline", "    2017-03-16 : MGL. First version.      2017-03-24 : MGL. Add header information about this processing step.      2017-06-01 : MGL. Use red_fitsaddpar. Change some added parameters.      2017-09-07 : MGL. Changed red_fitsaddpar --&gt; red_fitsaddkeyword.      2018-03-29 : MGL. Make fitsheader files for extra WB objects                  generated by use of TRACE keyword in redux config                  file.      2024-06-10 : MGL. Rewritten to cope better with both TRACE                  objects and mosaic observations.      2025-01-29 : MGL. New keyword cfg_tag.   ");
  
  

