  libdata[libdataItem++] = new Array("./red__summary.html#red::summary", "red::summary", 'routine in <a href="./red__summary.html">red__summary.pro</a>', "red__summary.pro", "", "red::summary", " Make a document with dataset summary and quicklook info.   Needs pdflatex to be installed, as well as one of pdfunite and  pdftk.    :Categories:      SST pipeline    :Author:      Mats Löfdahl, Institute for Solar Physics    :Keywords:     force : in, optional, type=boolean       Normally quicklook/quicklook_mosaic is run only if there are no      quicklook images. This keyword forces a rerun. Option      /core_and_wings is used by default, unless there are extra      keywords to be passed on to quicklook/quicklook_mosaic.    :History:     2025-12-07 : MGL. First version.   ", "_extraforceno_mosaicsno_regular", "          -1", "");
  
  

libdata[libdataItem++] = new Array("./red__sumpinh.html", "red__sumpinh.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__sumpinh.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__sumpinh.html#red::sumpinh", "red::sumpinh", 'routine in <a href="./red__sumpinh.html">red__sumpinh.pro</a>', "red__sumpinh.pro", " ", "red::sumpinh", " Sum pinhole images.   ", "nthreads      The number of threads to use for summing and bad-pixel filling.   dark_timestampflat_timestampno_descatter      Don't do back-scatter compensation.   ustat      Do only for this state.   prefilter       Set this keyword to the prefilter you want to sum pinholes        from. Otherwise, sum pinholes for all prefilters.   camsdirsoutdirpinhole_align       If true, then perform subpixel alignment of pinholes before        summing.   brightest_only       Set this to only sum (one of) the brightest tunings for each        prefilter.   lc_ignore       Set this to treat all lc states as if they were the same.   overwritesum_in_rdx", "CRISP pipeline", "   2013-06-04 : Split from monolithic version of crispred.pro.     2013-08-15 : MGL. Added keyword pinhole_align. Process cameras in                 loops instead of separately.     2013-08-27 : MGL. Added support for logging. Let the subprogram                 find out its own name.     2013-08-29 : MGL. Made use of nthread consistent. Loop over                 cameras rather than treating them one by one.     2013-08-30 : MGL. When keyword pinhole_align is set, request that                 red_sumfiles do: dark, flat, fillpix, alignment                 before summing.     2013-09-02 : MGL. Two new keywords, brightest_only and lc_ignore                 (but they don't actually do anything yet).     2013-09-03 : MGL. Fixed descattering bug.     2013-09-04 : MGL. Store also in floating point. This is the                 version used in red::pinholecalib.pro.     2016-02-15 : MGL. Use loadbackscatter. Remove keyword descatter,                 new keyword no_descatter.     2016-05-31 : THI. Re-write to use the class-methods.     2016-08-23 : THI. Rename camtag to detector and channel to camera,                 so the names match those of the corresponding SolarNet                 keywords.     2017-04-13 : MGL. Construct SOLARNET metadata fits header.     2017-07-06 : THI. Get framenumbers and timestamps from rdx_sumfiles                 and pass them on to red_sumheaders.     2016-08-10 : MGL. New keyword outdir.   ");
  
  

libdata[libdataItem++] = new Array("./red__sumpinh_new.html", "red__sumpinh_new.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red__sumpinh_new.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red__sumpinh_new.html#red::sumpinh_new", "red::sumpinh_new", 'routine in <a href="./red__sumpinh_new.html">red__sumpinh_new.pro</a>', "red__sumpinh_new.pro", " ", "red::sumpinh_new", " Sum pinhole images.   ", "nthreads       The number of threads to use for backscattering and bad-pixel filling.   no_descatter      Don't do back-scatter compensation.   ustat      Process these states. Overrides keywords all_tunings and       all_lcstates. Do not use together with keyword pref.   pref       Set this keyword to the prefilter you want to sum pinholes        from. Otherwise, sum pinholes for all prefilters. Do not use        together with keyword ustat.   pinhole_align       If true, then perform subpixel alignment of pinholes before        summing.   all_tunings       Set this to process all lambda tunings. Otherwise process only        the brightest tuning for each prefilter.   all_lcstates       Set this to process all lc states one by one, otherwise just        pick one.   overwrite       Overwrite existing output files.   ", "CRISP pipeline", "   2013-06-04 : Split from monolithic version of crispred.pro.     2013-08-15 : MGL. Added keyword pinhole_align. Process cameras in                 loops instead of separately.     2013-08-27 : MGL. Added support for logging. Let the subprogram                 find out its own name.     2013-08-29 : MGL. Made use of nthread consistent. Loop over                 cameras rather than treating them one by one.     2013-08-30 : MGL. When keyword pinhole_align is set, request that                 red_sumfiles do: dark, flat, fillpix, alignment                 before summing.     2013-09-02 : MGL. Two new keywords, brightest_only and lc_ignore                 (but they don't actually do anything yet).     2013-09-03 : MGL. Fixed descattering bug.     2013-09-04 : MGL. Store also in floating point. This is the                 version used in red::pinholecalib.pro.     2014-01-13 : MGL. New boolean for whether or not to do descatter.                 Added documentation and changed some variable names.                 Now stop if descatter is wanted but the backscatter                 psf or bgain does not exist.     2014-01-14 : MGL. Removed the (never used) keywords brightest_only                 and lc_ignore. Instead new keywords expressing the                 opposite choice (and therefore opposite default):                 all_tunings and all_lcstates. Removed alternate                 outdir. Implemented selection of brightest tuning and                 picking a single LC state.     2014-01-15 : MGL. Make an outer prefilter loop. The prefilter must                 be known at the point where we select states.                 Simplify use of nthreads keyword.     2014-01-16 : MGL. New keyword: overwrite. Save gain in the pinh/                 subdirectory to be used for display during the                 getalignclips step.     2016-02-15 : MGL. Use loadbackscatter. Remove keyword descatter,                 new keyword no_descatter.   ");
  
  

