  libdata[libdataItem++] = new Array("./red__sumpolcal.html#red::sumpolcal", "red::sumpolcal", 'routine in <a href="./red__sumpolcal.html">red__sumpolcal.pro</a>', "red__sumpolcal.pro", " ", "red::sumpolcal", " ", "check dirsnthreads       The number of threads to use for summing and backscatter correction.   outdir overwriteremove sum_in_rdx      Use rdx_sumfiles.   ucam ", "CRISP pipeline", "   2013-06-04 : Split from monolithic version of crispred.pro.     2013-07-09 : MGL. Worked around outdir1, outdir2, and lun when not                 specifying /old.     2013-07-10 : MGL. Worked around fzhead bug by using fzread                 instead.     2013-08-27 : MGL. Added support for logging. Let the subprogram                 find out its own name.     2017-07-06 : MGL. Adapt to new pipeline mechanisms. Add keywords                 dirs, outdir, sum_in_rdx. Add metadata handling.                 Remove keyword old.     2017-08-07 : MGL. New keyword nthreads.     2017-09-07 : MGL. Changed red_fitsaddpar --&gt; red_fitsaddkeyword.    ");
  
  

