  libdata[libdataItem++] = new Array("./red_apply_lowpass_postfilter.html#red_apply_lowpass_postfilter", "red_apply_lowpass_postfilter", 'routine in <a href="./red_apply_lowpass_postfilter.html">red_apply_lowpass_postfilter.pro</a>', "red_apply_lowpass_postfilter.pro", "    Mats Löfdahl, Institute for solar physics.   ", "red_apply_lowpass_postfilter", " Apply a lowpass filter to a cube of images.   ", "apodisation       By default, the input image is assumed to be apodised in order        to reduce the fft  dreadful cross . But if this keyword is        given and non-zero, then apodisation will be done. If the        value is unity, a default 1/16 of the image dimension will be        a smooth transition from 0 to 1. If the value is smaller than        unity, then that fraction will be used instead of the default.     fft_done : in, optional, type=boolean         If this keyword is set, im will be assumed to be the fourier        transform of the image rather than the image itself. Then the        apodisation keyword is ignored.     doplot : in, optional, type=boolean         Set this to plot results of various fits.     returnfourier : in, optional, type=boolean         Set this to return the Fourier transforms of the filtered        images.   fft_donedoplotreturnfourierims      The image on which the filter should be based. (But see keyword       fft_done)   filter      The low-pass filter to be applied to all images in ims.   ", "CRISP pipeline", "    2013-11-20 : MGL. First version.       A cube of low-pass filtered images.   ");
  
  

