  libdata[libdataItem++] = new Array("./red_convert_stonyhurst.html#red_convert_stonyhurst", "red_convert_stonyhurst", 'routine in <a href="./red_convert_stonyhurst.html">red_convert_stonyhurst.pro</a>', "red_convert_stonyhurst.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_convert_stonyhurst", " Convert Stonyhurst coordinates to Cartesian Helioprojective coordinates.   ", "helio      The input Stonyhurst coordinates as numbers, in arcsec.       Helio[0,*] = E/W = longitude; helio[1,*] = N/S = latitude.   stonyhurst_coordinates      Stonyhurst latitude and longitude, N pairs of coordinates to be       converted to HPLN,HPLT coordinates. If strings, then on the       form  N  2.02  W  0.16 , where the spaces are optional and N       could be S and W could be E. Stonyhurst coordinates are in       degrees.   isodate      The date in ISO format.   time      The time in seconds after midnight.   ", "SST pipeline", "   2021-12-08 : MGL. First version.     2021-12-15 : MGL. Use get_sun() from SolarSoft, adapted to SSTRED.    ");
  
  

libdata[libdataItem++] = new Array("./red_convl.html", "red_convl.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_convl.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_convl.html#red_convl", "red_convl", 'routine in <a href="./red_convl.html">red_convl.pro</a>', "red_convl.pro", "    Jaime de la Cruz Rodriguez (ISP-KVA 2010)   ", "red_convl", " Convolve a function with a kernel (1D), optionally using FFT.   ", "plot     Set this to make a plot.   usefft     Set this to use FFT, otherwise use convol() from IDL.   A      The  function  A. A is padded to n_elements(B)/2+2 points.   B      The  kernel . Must be on the same grid as A.   ", "CRISP pipeline", "   2013-06-04 : Split from monolithic version of crispred.pro.     2014-01-07 : PS. red_legend -&gt; al_legend (from astron)    ");
  
  

libdata[libdataItem++] = new Array("./red_convolve.html", "red_convolve.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_convolve.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_convolve.html#red_convolve", "red_convolve", 'routine in <a href="./red_convolve.html">red_convolve.pro</a>', "red_convolve.pro", "     Frank Varosi, NASA/GSFC 1992.   ", "red_convolve", " ", "FT_PSF      The Fourier transform of the PSF. Can be given as input to save       computing time, otherwise will give the FT as output. Ignored       if NO_FT.   FT_IMAGE      The Fourier transform of the image. Can be given as input to       save computing time, otherwise will give the FT as output.       Ignored if NO_FT.   NO_FT      Set this if you do not want to use FFT for the convolution.   CORRELATE      Set this to do correlation rather than convolution.   AUTO_CORRELATION     Set this to do auto-correlation. Incompatible with NO_FT.   image      The image to be convolved. (Not needed if Fourier transform is       sent in through FT_IMAGE.)   psf      The kernel or PSF to convolve with. (Not needed if       AUTO_CORRELATION keyword is set or Fourier transform is sent in       through FT_PSF.)   ", "CRISP pipeline", "   1997-10-?? : Converted to IDL V5.0. W. Landsman.     2013-06-04 : Split from monolithic version of crispred.pro.     2013-06-10 : Added documentation. Mats Löfdahl (MGL).    ");
  
  

libdata[libdataItem++] = new Array("./red_cpolcal_2d.html", "red_cpolcal_2d.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_cpolcal_2d.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_cpolcal_2d.html#red_cpolcal_2D", "red_cpolcal_2D", 'routine in <a href="./red_cpolcal_2d.html">red_cpolcal_2d.pro</a>', "red_cpolcal_2d.pro", "    2012-01-20 : P. Suetterlin, ISP   ", "red_cpolcal_2D", " Determine the 2D polarimetric calibration map of CRISP   Performs a Levenberg-Marquardt fit for the optimum MM of the CRISP  instrument. The actual computation is performed in an external C  routine that uses the C version of MPFIT by Craig Markward. The  external C code by Jaime de la Cruz Rodriguez (IFA-UU).   ", "chisq      Named variable to pass back the chi-square values of the fit   nthreads      Number of threads to use.   mask dat      polcal data, 4 LC states, N_q angles of the Quarter wave plate       (QWP), N_lp angles of the linear polarizer (LP).   qq      The actual QWP angles   lp       The actual LP angles   guess       Initial values. If omitted, they are computed from the        spatially averaged data   ", "CRISP pipeline", "   2013-06-04 : Split from monolithic version of crispred.pro.     2013-07-11 : MGL. Use red_polcal_fit, not polcal_fit.     2022-09-02 : PS. New keyword mask.          The external C library creduc.so has to be available.          ModMat: (float) array [4, 4, Sx, Sy] with the fitted modulation matrix                (MM) in each pixel   ");
  
  

