  libdata[libdataItem++] = new Array("./red_download_log.html#red_download_log", "red_download_log", 'routine in <a href="./red_download_log.html">red_download_log.pro</a>', "red_download_log.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_download_log", " Download log files for PIG and r0, possibly with uncompression and  other processing.   Compressed versions of the log files are preferred.   ", "localpath      The path to the downloaded and processed log file.   overwrite      Set this to overwrite a previously downloaded file. If a       compressed version has not been downloaded before, an existing       local file will be overwritten without /overwrite.   status      Zero for success, non-zero when problems.   instrument      The instrument to download the log file for, 'PIG' or 'R0'.   date      The date in ISO format.   outdir      The directory in which to write the log file.   ", "SST pipeline", "    2021-08-27 : MGL. First version.      2023-08-14 : MGL. Change parameters for rdx_convertlog.   ");
  
  

