libdata[libdataItem++] = new Array("./red_extractstates.html", "red_extractstates.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_extractstates.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_extractstates.html#red_extractstates", "red_extractstates", 'routine in <a href="./red_extractstates.html">red_extractstates.pro</a>', "red_extractstates.pro", "     Mats Löfdahl, ISP   ", "red_extractstates", " Extract states information from an array of strings (typically file  names).   Replaces the various versions of red_getstates. Based on regular  expressions and vectorization.   ", "is_wbis_pdstates        A struct containing some of the state information as string         arrays.   pstatespstates_outfullstate        The states in the form pref.wav.lc (see those keywords).   nums        The frame numbers.   wav        The wavelength tuning information in the form         tuning_finetuning, where tuning is the approximate wavelength         in Å and finetuning is the (signed) fine tuning in mÅ.   qwlc        The LC state.   lpcam        The camera name.   settings        Camera settings, like 12.00ms_G00.00.   pref        The prefilter wavelength in Å.   scan        The scan number.   dwav        The tuning in decimal form [Å].   lambda        The prefilter wavelength in decimal form [m].   rscan        ?? Can be removed when removed from prepmomfbd and prepmomfbd2.   hscan        ?? Can be removed when removed from prepmomfbd and prepmomfbd2.   focus        The focus added by the AO system (in order to compensate for         prefilters with optical power). Unit?   blue        Set this if it's data from a blue tower or tilt filter         camera. Will change what is returned in the fullstate and wav         keywords. Will not return anything in many keywords that are         only relevant for CRISP data.   basename        Set this to remove directory information from the beginning         of the strings.   strings      A list of strings from which to extract the states information.   ", "CRISP pipeline", "   2014-01-22 : First version.     2014-04-?? : MGL. Added keyword lambda.     2015-09-03 : MGL. Added the  blue  keyword, will now return                 something meaningful also for blue tilt filter data.                 Bugfix in qw regular expression.     2018-06-11 : MGL. Add conversion from CHROMIS wheel status to                 prefilter. New keywords is_wb and is_pd.     2025-06-17 : MGL. New keyword settings.   ");
  
  

libdata[libdataItem++] = new Array("./red_fdecomp.html", "red_fdecomp.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_fdecomp.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_fdecomp.html#red_fdecomp", "red_fdecomp", 'routine in <a href="./red_fdecomp.html">red_fdecomp.pro</a>', "red_fdecomp.pro", "", "red_fdecomp", " NAME:      red_FDECOMP  PURPOSE:      Routine to decompose file name(s) for any operating system.   CALLING SEQUENCE:      FDECOMP, filename, disk, dir, name, qual, [OSFamily = ]   INPUT:      filename - string file name(s), scalar or vector   OUTPUTS:      All the output parameters will have the same number of elements as        input filename         disk - disk name, always '' on a Unix machine, scalar or vector string        dir - directory name, scalar or vector string        name - file name, scalar or vector string        qual - qualifier, set equal to the characters beyond the last  .    OPTIONAL INPUT KEYWORD:      OSFamily -  scalar string specifying the operating system, must be either              'Windows' or 'unix'.    If not supplied,              then !VERSION.OS_FAMILY is used to determine the OS.  EXAMPLES:      Consider the following file names       unix:    file = '/itt/idl71/avg.pro'      Windows: file =  'd:\itt\idl71\avg.pro'       then IDL> FDECOMP,  file, disk, dir, name, qual        will return the following                   Disk             Dir          Name        Qual        Unix:      ''            '/itt/idl71/'  'avg'       'pro'        Windows:    'd:'         \itt\idl71\    'avg'       'pro'   NOTES:      (1) The period is removed between the name and qualifier      (2) Unlike the intrinsic FILE_BASENAME() and FILE_DIRNAME() functions,          one can use FDECOMP to decompose a Windows file name on a Unix machine          or a Unix filename on a Windows machine.   ROUTINES CALLED:      None.  HISTORY      version 1  D. Lindler  Oct 1986      Include VMS DECNET machine name in disk    W. Landsman  HSTX  Feb. 94      Converted to Mac IDL, I. Freedman HSTX March 1994      Major rewrite to accept vector filenames V5.3   W. Landsman June 2000      Fix cases where disk name not always present  W. Landsman  Sep. 2000      Make sure version defined for Windows  W. Landsman April 2004      Include final delimiter in directory under Windows as advertised                 W. Landsman   May 2006      Remove VMS support, W. Landsman    September 2006      Remove MacOS branch (same as Unix) W. Landsman  August 2009       Renamed red_fdecomp for inclusion in the CRISPRED pipeline. MGL      2013-07-11.   ", "OSfamilyfilenamediskdirnamequalversion", "          -1", "");
  
  

