  libdata[libdataItem++] = new Array("./red_fitgrid.html#red_fitgrid", "red_fitgrid", 'routine in <a href="./red_fitgrid.html">red_fitgrid.pro</a>', "red_fitgrid.pro", "    Mats Löfdahl   ", "red_fitgrid", " Fit pinhole positions to a rectangular grid. Robust with respect to  missing (blocked) pinholes.   ", "dx_initdy_initdebug      Use when debugging.   im      A pinhole image.   ", "CRISP pipeline", "    2013-09-16 : MGL. First version.      2019-12-06 : MGL. New keywords dx_init and dy_init. Remove                  pinholes near array limits. Improve the initial                  fitting in X and Y.      2024-06-18 : MGL. Re-implemented       The grid parameters as a structure, { x0:x0, y0:y0, dx:dx, dy:dy,     theta:theta}, where (X0,y0) are the pixel coordinates of one     point in the grid, dx and dy are the grid spacings in X and Y     resp., and theta is a rotation angle in radians.   ");
  
  

