libdata[libdataItem++] = new Array("./red_fits_createfile.html", "red_fits_createfile.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_fits_createfile.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_fits_createfile.html#red_fits_createfile", "red_fits_createfile", 'routine in <a href="./red_fits_createfile.html">red_fits_createfile.pro</a>', "red_fits_createfile.pro", "    Mats Löfdahl   ", "red_fits_createfile", " Create a fits file to write data cube slices into when you don't  want to have the entire cube in memory at the same time.   Usage:   mkhdr,head,type,naxisx   ; Make a FITS header appropriate for your data cube.  sxaddpar,hdr,...         ; Add whatever information you want   red_fits_createfile, 'file.fits', head, lun, fileassoc [, tabhdu = tabhdu ]  for i=0,N-1 do begin     im = ... ; Calculate image number i.     fileassoc[i]=im  endfor  free_lun,lun   Binary extensions can be included by use of the tabhdu keyword.   ", "tabhdu       Binary extensions to be added to the fits file. See        documentation in red_writedata.pro.   wcs_time       WCS time coordinate to be added in a binary extension.   wcs_wavelength       WCS wavelength coordinate to be added in a binary extension.   wcs_time_dimensionwcs_wavelength_dimensionfilename       The name of the file to create.   head       The complete fits header of the file. The NAXIS* and BITPIX        keywords are used to set the file up.   lun       The logical unit of the opened file.   fileassoc       An assoc variable that can be used to write (and read!) data        slices.   ", "SST pipeline", "    2016-11-07 : MGL. First version.      2016-12-07 : MGL. New keyword tabhdu.      2017-03-23 : MGL. New keywords wcs_time and wcs_wavelength.   ");
  
  

libdata[libdataItem++] = new Array("./red_fits_var_keys.html", "red_fits_var_keys.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_fits_var_keys.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_fits_var_keys.html#red_fits_var_keys", "red_fits_var_keys", 'routine in <a href="./red_fits_var_keys.html">red_fits_var_keys.pro</a>', "red_fits_var_keys.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fits_var_keys", " Return the keywords in the VAR_KEYS keyword from a FITS header.  Optionally add a keyword, both to output and to the keyword in the  header.   ", "count       The number of variable keywords (including any added keyword).   extensions       The extension names in which the returned keywords can be        found.   new_keyword       A keyword to be added.   new_extension       The extension of the new keyword, constructed from the        new_keyword.   var_keys       The VAR_KEYS keyword value (with optional new_keyword added).   hdr       The FITS header.   ", "SST pipeline", "   2017-09-05 : MGL. First version.     2017-09-08 : MGL. New keywords new_keyword and new_extension.     2018-11-02 : MGL. New keyword count.       The VAR_KEYS string value.   ");
  
  

libdata[libdataItem++] = new Array("./red_fitsaddkeyword.html", "red_fitsaddkeyword.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_fitsaddkeyword.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_fitsaddkeyword.html#red_fitsaddkeyword", "red_fitsaddkeyword", 'routine in <a href="./red_fitsaddkeyword.html">red_fitsaddkeyword.pro</a>', "red_fitsaddkeyword.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitsaddkeyword", " Add a parameter to a FITS header, wrapper around fxaddpar.   The routine implements record-valued keywords, see the Calabretta et  al. draft from 2004,  Representations of distortions in FITS world  coordinate systems . Contrary to  normal  keywords, record-valued  keywords can occur added multiple times (with different field  specifiers) in a header. But with red_fitsaddkeyword you can only  add them in the same call, any old occurences are removed. It is the  user's responsibility to make sure any combination of keyword and  field-specifier is only added once in this call.   ", "anchor        The name of the parameter relative to which this parameter         will be positioned. Decide on before/after based on logical         value of those two keywords. (Don't use COMMENT or HISTORY as         anchor!)   afterbeforeforce        Set this to force positioning for existing keywords. Implied         by anchor keyword.   nodelete        The default behavior is to delete existing instances of the         same HIERARCH keyword. With /nodelete this is not done.   _ref_extraheader        The FITS header. See documentation for fxaddpar.   name        The name of the added parameter/keyword. See documentation         for fxaddpar, but here it can be an array. If name has two         parts, separated by a space character, the first part is         interpreted as the name of a record-valued keyword with the         second part as the field-specifier.   value        Value for the added parameter. See documentation for         fxaddpar, but here it can be an array. The array notation for         multiple keywords means only keywords with the same value         type (string, float, integer, ...) can be added in a single         call.   comment        A comment. See documentation for fxaddpar, but here it can be         an array.   ", "SST pipeline", "    2017-05-30 : MGL. First version.      2017-07-17 : MGL. Make robust to name and value being unit length                  arrays.      2017-09-05 : MGL. Parameters name, value, comment can be arrays.                  Override some of the positioning of fxaddpar by                  protecting blank and COMMENT keywords.      2017-09-06 : MGL. Line-wrap blank and COMMENT keywords if needed.                  Remove trailing blank lines.      2017-09-06 : MGL. Renamed from red_fitsaddpar.      2017-10-26 : MGL. Implemented record-valued keywords.      2017-11-13 : MGL. Implemented HISTORY keywords.      2018-03-27 : MGL. Record-valued keywords, values with zero                  decimals are printed as integers.      2019-09-30 : MGL. New keyword nodelete.   ");
  
  

libdata[libdataItem++] = new Array("./red_fitsaddkeyword_hierarch.html", "red_fitsaddkeyword_hierarch.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_fitsaddkeyword_hierarch.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_fitsaddkeyword_hierarch.html#red_fitsaddkeyword_hierarch", "red_fitsaddkeyword_hierarch", 'routine in <a href="./red_fitsaddkeyword_hierarch.html">red_fitsaddkeyword_hierarch.pro</a>', "red_fitsaddkeyword_hierarch.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitsaddkeyword_hierarch", " Add a HIERARCH keyword to a FITS header.   The routine implements HIERARCH keywords, see Wicenec, A., Grosbol,  P., & Pence, W. 2009,  The ESO HIERARCH Keyword Conventions ,  https://fits.gsfc.nasa.gov/registry/hierarch/hierarch.pdf. Contrary  to  normal  keywords, HIERARCH keywords can occur multiple times  (with different field specifiers) in a header. With  red_fitsaddkeyword you can only add them in the same call, any old  occurences are removed. It is the user's responsibility to make sure  any combination of keyword and field-specifier is only added once in  this call.   ", "anchor        The name of the parameter relative to which this parameter         will be positioned. Decide on before/after based on logical         value of those two keywords. (Don't use COMMENT or HISTORY as         anchor!)   afterbeforeforce        Set this to force positioning for existing keywords. Implied         by anchor keyword.   nodelete        The default behavior is to delete existing instances of the         same HIERARCH keyword. With /nodelete this is not done.   _ref_extrahdrname        The name of the added parameter/keyword. See documentation         for fxaddpar, but here it can be an array. If name has two         parts, separated by a space character, the first part is         interpreted as the name of a record-valued keyword with the         second part as the field-specifier.   fields        Fields for the added parameter, the lists should consist of         two or three elements: the field name, the value, and an         optional comment.   ", "SST pipeline", "   2018-04-06 : MGL. First version.     2019-09-30 : MGL. New keyword nodelete.   ");
  
  

