  libdata[libdataItem++] = new Array("./red_fitscopykeyword.html#red_fitscopykeyword", "red_fitscopykeyword", 'routine in <a href="./red_fitscopykeyword.html">red_fitscopykeyword.pro</a>', "red_fitscopykeyword.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitscopykeyword", " Copy a keyword from one FITS header to another.   Do not use for record-valued keywords or SOLARNET variable-keywords.   ", "_ref_extra        Any keywords are used when calling red_fitsaddkeyword.   hdr        The target FITS header.   name        The name of the parameter/keyword to be copied. See         documentation for fxaddpar.   oldhdr1        The source FITS header.   oldhdr2        A second source FITS header.   ", "SST pipeline", "    2017-12-06 : MGL. First version.   ");
  
  

libdata[libdataItem++] = new Array("./red_fitscube_addboundingbox.html", "red_fitscube_addboundingbox.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_fitscube_addboundingbox.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_fitscube_addboundingbox.html#red_fitscube_addboundingbox", "red_fitscube_addboundingbox", 'routine in <a href="./red_fitscube_addboundingbox.html">red_fitscube_addboundingbox.pro</a>', "red_fitscube_addboundingbox.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitscube_addboundingbox", " Add BoundingBox keywords.   ", "anchor      See red_fitsaddkeyword.pro   checksum      Check the CHECKSUM keyword before adding new keywords and       update it afterwards.   hdr      A header to be updated. If present, don't read the header from       the file and don't write it either. Also implies checksum=0.   filename      The path of the fitscube file.   ", "SST pipeline", "    2026-05-12 : MGL. First version.    ");
  
  

