  libdata[libdataItem++] = new Array("./red_fitscube_addcmap.html#red_fitscube_addcmap", "red_fitscube_addcmap", 'routine in <a href="./red_fitscube_addcmap.html">red_fitscube_addcmap.pro</a>', "red_fitscube_addcmap.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitscube_addcmap", " Add a cavity map cube to a fitscube file using an extension of the  mechanisms in the WCS distortions draft (Calabretta et al. 2004).   ", "cmap_number       Used to distinguish between cavity maps for multiple (CHROMIS)        prefilters. The value of the EXTVER keyword in the extensions        header, as well as DW3.EXTVER in the main header.   prefilter       The prefilter tag.   indx       The tuning pixel coordinate indices for which this cavity map        applies.   filename       The name of the file in which to add the cavity maps.   cmaps       The 3D cube with cavity maps, each adapted to one of the scans        in the fitscube file. Unit is nm.   ", "SST pipeline", "    2017-10-31 : MGL. First version.      2017-03-22: MGL. Implement extension of (Calabretta et al. 2004).      2018-04-06 : MGL. The Calabretta mechanism is not enough, instead                  use new extension of this mechanism with keywords                  stored both with the Calabretta record-valued                  mechansim and the HIERARCH convention.      2019-09-25 : MGL. Implement writing multiple wavelength                  distortions (cavity maps).      2019-09-30 : MGL. Make it a regular subroutine, not a class                  method.      2021-05-03 : MGL. Do not write the HIERARCH version of DW3. Add                  DISTNAME in the extension header.    ");
  
  

libdata[libdataItem++] = new Array("./red_fitscube_addframe.html", "red_fitscube_addframe.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_fitscube_addframe.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_fitscube_addframe.html#red_fitscube_addframe", "red_fitscube_addframe", 'routine in <a href="./red_fitscube_addframe.html">red_fitscube_addframe.pro</a>', "red_fitscube_addframe.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitscube_addframe", " Add a frame to a fitscube file.   ", "iframe       The frame index in the data cube seen as a 3D cube.   ituning       The tuning index, used to calculate iframe.   istokes       The stokes index, used to calculate iframe.   iscan       The scan index, used to calculate iframe.   fitscube_info       Structure with dimensions, lun and header.   filename_or_fileassocframe       The image frame to add.   ", "SST pipeline", "    2016-03-24 : MGL. First version.      2017-11-01 : MGL. Get the cube dimensions from the file instead                  of from keywords.      2017-11-03 : MGL. New keyword iframe.      2020-03-23 : OA. Added 'fitscube_info' keyword.   ");
  
  

libdata[libdataItem++] = new Array("./red_fitscube_addgavokeywords.html", "red_fitscube_addgavokeywords.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_fitscube_addgavokeywords.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_fitscube_addgavokeywords.html#red_fitscube_addgavokeywords", "red_fitscube_addgavokeywords", 'routine in <a href="./red_fitscube_addgavokeywords.html">red_fitscube_addgavokeywords.pro</a>', "red_fitscube_addgavokeywords.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitscube_addgavokeywords", " Add keywords required by GaVO DaCHs to a fitscube header.   Add RESOLVPW, CSPMINn/MAXn, CBBMINn/MAXn and CROTA.  Also OBS_MODE and POINT_ID (if missing)   ", "anchor      See red_fitsaddkeyword.pro   checksumcrota      Counterclockwise rotation of the FOV in degrees. If not given,       don't add the CROTA keyword.   hdr      A header to be updated. If present, don't read the header from       the file and don't write it either. Also implies checksum=0.   filename      The path of the fitscube file.   ", "SST pipeline", "    2026-06-24 : MGL. First version.    ");
  
  

