  libdata[libdataItem++] = new Array("./red_fitscube_addrespappl.html#red_fitscube_addrespappl", "red_fitscube_addrespappl", 'routine in <a href="./red_fitscube_addrespappl.html">red_fitscube_addrespappl.pro</a>', "red_fitscube_addrespappl.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitscube_addrespappl", " Add or uppdate RESPAPPL (APPLied RESPonse function) variable keyword.   ", "anchor      Place the RESPAPPL header keyword after this keyword.   axis_numbers      The fitscube pixel axis numbers that the response function was       applied to.   scans_dimension      Whether the scans dimension is represented in the response       function.   tuning_dimension      Whether the tuning dimension is represented in the response       function.   updatefilename      The name of the file in which to add or update the RESPAPPL       variable keyword.   respappl      The applied response function for one of or both the tuning and       scans dimensions.   ", "SST pipeline", "   2021-02-26 : MGL. First version.    ");
  
  

libdata[libdataItem++] = new Array("./red_fitscube_addvarkeyword.html", "red_fitscube_addvarkeyword.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_fitscube_addvarkeyword.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_fitscube_addvarkeyword.html#red_fitscube_addvarkeyword", "red_fitscube_addvarkeyword", 'routine in <a href="./red_fitscube_addvarkeyword.html">red_fitscube_addvarkeyword.pro</a>', "red_fitscube_addvarkeyword.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitscube_addvarkeyword", " Add data to a FITS file using the Variable-Keyword mechanism of the  SOLARNET document, appendix I.   To make implementation easier, we'll have each keyword in an  extension of its own. The extenstion's name is  VAR-EXT-  followed  by the name of the keyword.   ", "old_filenameaxis_numbers       For a pixel-to-pixel association with, e.g., NAXIS2 and        NAXIS4, use axis_numbers=[2,4].     flipped : in, optional, type=boolean         Set this if the keyword should be added to a  flipped  cube.        Only needed for coordinate-association keywords but does no        harm for other association types.     comment : in, optional, type=string         The keyword comment in the main header.     keyword_value : in, optional, type=varies         The keyword value in the main header.     keyword_method : in, optional, type=string, default='first'         The keyword value in the main header to be calculated with        this method. One of 'first', 'last', 'mean', 'median', 'min',        'max'.     old_filename : in, optional, type=string         If this is given, any values parameter (and many other        keywords) will be ignored and the information will be        collected from this file instead.     update : in, optional, type=boolean         If the keyword already exists, update it.     _ref_extra :  in, optional         Any extra keywords are used when positioning keywords in the        main header, see red_fitsaddkeyword.   keyword_valuekeyword_methodcommenttunitextra_coordinate1extra_coordinate2extra_labelsextra_namesextra_unitsspatial_coordinatesspatial_deltasspatial_unitstime_coordinatetime_deltatime_unitupdatewavelength_coordinateswavelength_deltawavelength_unitsflipped_ref_extrafilename       The name of the file in which to add the variable-keyword.   keyword_name       The name of the keyword.   values      The values of the variable-keyword. If this is not given,       keyword old_filename must be given and the keyword will be       taken from there.   ", "SST pipeline", "   2017-09-06 : MGL. First version, supporting pixel-to-pixel                 association and coordinate association for tabulated                 time.     2017-09-07 : MGL. Changed red_fitsaddpar --&gt; red_fitsaddkeyword.     2017-09-08 : MGL. New keyword old_filename.     2017-09-13 : MGL. New keyword flipped.     2018-06-13 : MGL. New keyword keyword_method. Allow keyword                 positioning keywords.     2021-02-26 : MGL. New keyword update.   ");
  
  

libdata[libdataItem++] = new Array("./red_fitscube_addwcs.html", "red_fitscube_addwcs.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_fitscube_addwcs.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_fitscube_addwcs.html#red_fitscube_addwcs", "red_fitscube_addwcs", 'routine in <a href="./red_fitscube_addwcs.html">red_fitscube_addwcs.pro</a>', "red_fitscube_addwcs.pro", "    Mats Löfdahl, ISP   ", "red_fitscube_addwcs", " Add a WCS extension to a fitscube file.   This was inspired by Stein's wcs_crosstabulation.pro   ", "csyer_spatial_value       Upper limit of systematic error in the spatial cordinates (in        arcsec), used to set the value of FITS header keywords CSYER1        and CSYER2. The default 60 arcsec is for when the rotation is        unspecified.   csyer_spatial_comment       The comment for FITS header keywords CSYER1 and CSYER2.   dimensions       The dimensions of the data cube.   no_extension       Only add the header keywords, not the extension.   update       Update an existing WCS extension.   filename       The name of the file.   wcs       The WCS coordinates hpln, hplt, wave, time as fltarr(2, 2,        Ntunes, Nscans) arrays.   ", "SST pipeline", "    2016-03-24 : MGL. First version.      2016-08-25 : MGL. Add spatial coordinates.      2016-09-28 : MGL. Add a new parameter wcs.      2016-10-11 : MGL. Remove keywords                  wcs_{hpln,hplt,wave,time}_coordinate.      2017-10-18 : MGL. WCS related file header keywords moved here                  from fitscube_initialize method. New keyword                  dimensions.      2018-01-16 : MGL. Allow for degenerate trailing dimensions of                  scan-only cubes.      2018-11-29 : MGL. New keyword no_extension.      2019-09-13 : MGL. A version that is not a class method.      2020-03-23 : MGL. New keyword update.      2020-03-27 : MGL. New keywords csyer_spatial_value and                  csyer_spatial_comment.   ");
  
  

