  libdata[libdataItem++] = new Array("./red_fitscube_copyextensions.html#red_fitscube_copyextensions", "red_fitscube_copyextensions", 'routine in <a href="./red_fitscube_copyextensions.html">red_fitscube_copyextensions.pro</a>', "red_fitscube_copyextensions.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitscube_copyextensions", " Copy extensions from one fitscube file to another.   No check for unique extension names is done. If an extension name is  asked for, all extensions with that name are copied (or ignored). It  doesn't matter if an extension name is asked for multiple times.   ", "anchor        Passed on to red_fitscube_addvarkeyword for extensions that         are variable keywords.   ext_list        Names or indices of extensions to be copied (default) or         ignored (if /ignore keyword is set).   ext_regex        Add to ext_list all existing extensions that match any of         these regular expressions.   ext_statistics        Add to ext_reqex regular expressions that match extensions         corresponding to statistics variable keywords.   ignore        Interpret ext_list as a list of extensions to ignore.   infile       The name of the original file, from which to copy the        extensions.   outfile       The name of the target file, to which the extensions should be        copied.   ", "SST pipeline", "    2020-10-16 : MGL. First version.      2022-03-30 : MGL. New keywords ext_regex and ext_statistics.   ");
  
  

