  libdata[libdataItem++] = new Array("./red_fitscube_open.html#red_fitscube_open", "red_fitscube_open", 'routine in <a href="./red_fitscube_open.html">red_fitscube_open.pro</a>', "red_fitscube_open.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitscube_open", " Open a fitscube file.   ", "header      The header of the file.   lun      The logical unit of the opened file.   update      Open with openu rather than openr.   filename      The name of the fitscube file to open.   fileassoc      An assoc variable set up to access the frames in the file.   fitscube_info      Info about the opened fitscube file, including the header, the       cube dimensions, and the logical unit.   ", "SST pipeline", "      2019-04-03 : MGL. First version.        2019-08-23 : MGL. New keyword update.   ");
  
  

libdata[libdataItem++] = new Array("./red_fitscube_plotspectrum.html", "red_fitscube_plotspectrum.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_fitscube_plotspectrum.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_fitscube_plotspectrum.html#red_fitscube_plotspectrum", "red_fitscube_plotspectrum", 'routine in <a href="./red_fitscube_plotspectrum.html">red_fitscube_plotspectrum.pro</a>', "red_fitscube_plotspectrum.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitscube_plotspectrum", " Plot median spectrum of fitscube with atlas.   ", "axis_numbers      The fitscube pixel coordinates axis numbers of the       frame_statistics array. Used for multiple calls with the same       filename.   disk_center      Disk center data should match the atlas spectrum but might not       because of a failed intensity level correction. With this       keyword set, plot also the data spectrum adjusted to the atlas       intensity level (blue + symbols).   frame_statistics      Intensity statistics for the frames of the fitscube. Used for       multiple calls with the same filename.   himargin      Extend upper end of xrange by this many percent of the       wavelength range of the data.   lomargin      Extend lower end of xrange by this many percent of the       wavelength range of the data.   nosave      Do not save the plot as a pdf file.   testtitle      Used as plot title.   xrange      Set xrange of plot explicitly.   yrange      Set yrange of plot explicitly (*10E-9).   filename      The name of the file to plot the spectrum of.   ", "SST pipeline", "   2021-03-02 : MGL. First version.     2021-07-22 : OA. Added 'yrange' keyword.     2021-09-08 : MGL. New keyword disk_center.    ");
  
  

