  libdata[libdataItem++] = new Array("./red_fitscube_statistics.html#red_fitscube_statistics", "red_fitscube_statistics", 'routine in <a href="./red_fitscube_statistics.html">red_fitscube_statistics.pro</a>', "red_fitscube_statistics.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_fitscube_statistics", " Calculate statistics for the frames in a fitscube file.   ", "axis_numbers      The fitscube pixel coordinates axis numbers of the       frame_statistics output.   cube_comments hist      The accumulated histogram.   percentiles     The percentiles to calculate.   remove_only     Only remove existing statistics keywords.   update     Calculate (new) statistics only if there are statistics in the      header already.   write     Write the statistics to the fitscube.   filename frame_statistics      Frame by frame statistics.   cube_statistics      Statistics for the entire cube.   ", "SST pipeline", "   2019-03-28 : MGL. First version.     2019-04-05 : MGL. Use red_fitscube_open and red_fitscube_close.     2019-08-26 : MGL. New keyword remove_only.     2020-01-21 : MGL. New keyword update.     2020-11-01 : MGL. Remove keywords angles, full, grid, orgiNx,                 origNy, and shifts.     2021-03-03 : MGL. New keyword axis_numbers.     2021-04-07 : MGL. New keyword hist.   ");
  
  

