  libdata[libdataItem++] = new Array("./red_image_statistics_combine.html#red_image_statistics_combine", "red_image_statistics_combine", 'routine in <a href="./red_image_statistics_combine.html">red_image_statistics_combine.pro</a>', "red_image_statistics_combine.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_image_statistics_combine", " Combine statistics for multiple images into statistics for a data  cube.   ", "binsize       THe bin size of hist. Must be given for the percentiles to be        calculated.   commentshist       A histogram for the entire cube. Must be given for the        percentiles to be calculated.   old       Use old, deprecated algorithm.   statsarr       An array of structs as returned by        red_image_statistice_calculate.   ", "SST pipeline", "   2018-10-26: MGL. First version.     2019-05-29: MGL. Improve percentiles by interpolating in the                cumulative histogram.     2020-11-30: MGL. Add DATANRMS, remove DATARMS.     2021-04-05: MGL. Implement algorithm by Pébay et al. for combining                the moments.       A struct with statistics.   ");
  
  

