  libdata[libdataItem++] = new Array("./red_limb_darkening.html#red_limb_darkening", "red_limb_darkening", 'routine in <a href="./red_limb_darkening.html">red_limb_darkening.pro</a>', "red_limb_darkening.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_limb_darkening", " A normalized limb darkening function of wavelength and mu=cos(theta).   ", "neckel_coeffs        The coefficients from Neckel & Labs (1994).   analytical        Get coefficients from Neckel (2005) instead.   lambda       The wavelength in units of meters.   mu       The mu values.   ", "SST pipeline", "    2021-09-06 : MGL. First version, based on private IDL library                  function neckel_p5().       The limb darkening function values.   ");
  
  

