  libdata[libdataItem++] = new Array("./red_momfbd_renormalize.html#red_momfbd_renormalize", "red_momfbd_renormalize", 'routine in <a href="./red_momfbd_renormalize.html">red_momfbd_renormalize.pro</a>', "red_momfbd_renormalize.pro", "   Mats Löfdahl, Institute for Solar Physics, mats@astro.su.se.   ", "red_momfbd_renormalize", " The Zernike and Karhunen-Loeve modes used internally in the MOMFBD  program are not normalized to unit RMS. This routine  normalizes the modes and rescales the coefficients to match the  new modes.   Before this is done, one cannot calculate variances of the  estimated wavefronts by summing the squares of the coefficients.   ", "verbose     Set this for more printout.   mr     A structure as read with the momfbd_read command. On output,      same structure but with alpha and modes renormalized.   ", "Image restoration mombfd", "   2010-09-21: Written by Mats Löfdahl     2012-11-21 : Switched to docformat 'rst'.     2013-08-30 : MGL. Renamed for inclusion in crispred pipeline.     2014-05-15 : MGL. Don't use non-standard function  dimen .   ");
  
  

