  libdata[libdataItem++] = new Array("./red_mysql_cmd.html#red_mysql_cmd", "red_mysql_cmd", 'routine in <a href="./red_mysql_cmd.html">red_mysql_cmd.pro</a>', "red_mysql_cmd.pro", "    Mats Löfdahl, Institute for Solar Physics.      Based on mysqlcmd.pro by Marc W. Buie, Lowell Observatory.   ", "red_mysql_cmd", " Send a command to open database and collect the answer.   ", "debuglun       The logical unit of the pipe (opened by red_mysql_open).   query       Command line(s) to send to pipe.   answer       Returned information from query (possible string array).   nlines       Number of lines of returned information (may be zero).   ", "SST pipeline", "  2002-04-10 : MWB. First version.    2018-06-28 : MGL. Renamed  red_mysql_cmd  for inclusion in SST data                pipelines. Adaptions to SST style.   ");
  
  

