libdata[libdataItem++] = new Array("./red_mysql_open.html", "red_mysql_open.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_mysql_open.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_mysql_open.html#red_mysql_open", "red_mysql_open", 'routine in <a href="./red_mysql_open.html">red_mysql_open.pro</a>', "red_mysql_open.pro", "", "red_mysql_open", " Open a mySQL database for operations via a pipe.   Assumes that your .my.cnf file points to the correct mysql server  and that it includes the login information. Also, the command  'mysql' must appear in your default path.   :Categories:      SST pipeline    :Author:      Mats Löfdahl, Institute for Solar Physics      Based on openmysql.pro by Marc W. Buie, Lowell Observatory   :Returns:    :Params:       dbname : in, type=string          Name of database to open at start.       error : out, type=integer          Return value indicating if the open call succeeded. If error         is zero, the open was good and the lun is ready for use. If         error is not zero, the lun will not point to an open file and         the !error_state system variable will contain more         information if you want it.       lun : out, integer          The logical unit of the pipe (use free_lun to close).   :Keywords:       host : out, optional, type=string             Host name of the server to connect to for queries.  The default            is to use the host name specified in your .my.conf configuration            file.       user  : out, optional, type=string             User name to be used for the connection.  This is the user name            as understood by mysql and has no relationship to the user name            of the calling process.  The default is to use the user name            specified in your .my.conf configuration file.      socket : out, optional, type=string             String, identifies socket for client to read and write from.            default is to not use a socket.       PW : in, optional, type=string             The mysql password.   :History:    2002-01-09 : MWB. First version.    2006-12-08 : MWB. Added error output argument, now can indicate if                open failed    2007-09-06 : MWB. Added HOST/USER keywords    2010-03-05 : MWB. Added the EXTRACONFIG keyword    2011-11-23 : Jarle Brinchmann, Leiden Univ., Add SOCKET keyword to                support reading from sockets    2018-06-28 : MGL. Renamed from original  openmysql  to                 red_mysql_open  for inclusion in SST data pipelines.                Adaptions to SST style. New keyword pw.   ", "hostuserpwextraconfigsocketlundbnameerror", "          -1", "");
  
  

libdata[libdataItem++] = new Array("./red_mysql_open_remote.html", "red_mysql_open_remote.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_mysql_open_remote.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_mysql_open_remote.html#red_mysql_open_remote", "red_mysql_open_remote", 'routine in <a href="./red_mysql_open_remote.html">red_mysql_open_remote.pro</a>', "red_mysql_open_remote.pro", "", "red_mysql_open_remote", " Open a mySQL database for operations via a pipe.   Assumes that your .my.cnf file points to the correct mysql server  and that it includes the login information. Also, the command  'mysql' must appear in your default path.   :Categories:      SST pipeline    :Author:      Mats Löfdahl, Institute for Solar Physics      Based on openmysql.pro by Marc W. Buie, Lowell Observatory   :Returns:    :Params:       dbname : in, type=string          Name of database to open at start.       error : out, type=integer          Return value indicating if the open call succeeded. If error         is zero, the open was good and the lun is ready for use. If         error is not zero, the lun will not point to an open file and         the !error_state system variable will contain more         information if you want it.       lun : out, integer          The logical unit of the pipe (use free_lun to close).   :Keywords:       host : out, optional, type=string             Host name of the server to connect to for queries.  The default            is to use the host name specified in your .my.conf configuration            file.       user  : out, optional, type=string             User name to be used for the connection.  This is the user name            as understood by mysql and has no relationship to the user name            of the calling process.  The default is to use the user name            specified in your .my.conf configuration file.      socket : out, optional, type=string             String, identifies socket for client to read and write from.            default is to not use a socket.       PW : in, optional, type=string             The mysql password.   :History:    2002-01-09 : MWB. First version.    2006-12-08 : MWB. Added error output argument, now can indicate if                open failed    2007-09-06 : MWB. Added HOST/USER keywords    2010-03-05 : MWB. Added the EXTRACONFIG keyword    2011-11-23 : Jarle Brinchmann, Leiden Univ., Add SOCKET keyword to                support reading from sockets    2018-06-28 : MGL. Renamed from original  openmysql  to                 red_mysql_open  for inclusion in SST data pipelines.                Adaptions to SST style. New keyword pw.    2019-10-08 : OA. Renamed version that should run on La Palma.   ", "hostuserpwextraconfigsocketlundbnameerror", "          -1", "");
  
  

libdata[libdataItem++] = new Array("./red_mysql_query.html", "red_mysql_query.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_mysql_query.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_mysql_query.html#red_mysql_query", "red_mysql_query", 'routine in <a href="./red_mysql_query.html">red_mysql_query.pro</a>', "red_mysql_query.pro", "", "red_mysql_query", " Submit MySQL query and get response as vectors of data.   Submit a simple SQL query to MySQL server, using the connection  previously opened with openmysql. Retrieve the result into a row of  variables, much as readcol does.   Requires an open connection to MySQL server (established by use of  openmysql) as well as valid permissions for whatever query or  command is to be executed.   Callin sequence: red_mysql_query,lun,query,[varables...],[format='(a,f,...)']   :Categories:      SST pipeline    :Author:      Mats Löfdahl, Institute for Solar Physics.      Based on mysqlquery.pro by Will Grundy.   :Params:      lun : in, type=integer        The logical unit of the pipe (opened by openmysql).      variables : out        A list of variables to recieve columns of output. Default type       is ascii, but use the format keyword to specify other data       types.      query : in, type=strarr        Command(s) to send to pipe.    :Keywords:      heads : out, type=string        Array of column heads.      Ngood : out, type=integer        Number of valid lines found that were read.      format : in, type=string        Specify format of output variables (default is ascii).      verbose : in, type=boolean        Flag turns on debugging output to standard out.   :History:     2002-02-14 : WG. Adapted from earlier version called mysql.pro     2002-02-27 : WG. Changed behavior so 'NULL' becomes NaN instead of                 making the line be ignored when it occurs in a                 numerical field.     2002-03-25 : WG. Changed to split on tab instead of white space,                 so that strings with internal spaces (but not tabs)                 can be retrieved.     2003-01-10 : MWB. Fixed multi-line query error. Only one query per                 call is allowed.     2006-11-09 : PLC. Changed strsplit call to use /preserve_null flag                 this means a field can now return an empty string.                 The behavior for non-'a' type fields is not defined                 in this case.     2007-07-15 : MWB. Added NGOOD output keyword     2010-03-11 : MWB. Change behavior so that if there is only one                 valid line the result is returned as a scalar instead                 of a one-element vector.     2014-03-07 : MWB. Increased number of returned variables to 35.     2016-11-14 : MWB. Fix to LL format code handling, propagated from                 readcol     2018-06-28 : MGL. Renamed  red_mysql_query  for inclusion in SST                 data pipelines. Adaptions to SST style. Removed                 keyword cmd.   ", "formatheadsverbosengoodlunqueryv1v2v3v4v5v6v7v8v9v10v11v12v13v14v15v16v17v18v19v20v21v22v23v24v25v26v27v28v29v30v31v32v33v34v35", "          -1", "");
  
  

libdata[libdataItem++] = new Array("./red_mysql_quote.html", "red_mysql_quote.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_mysql_quote.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_mysql_quote.html#red_mysql_quote", "red_mysql_quote", 'routine in <a href="./red_mysql_quote.html">red_mysql_quote.pro</a>', "red_mysql_quote.pro", "    Mats Löfdahl, Institute for Solar Physics      Originally by Marc W. Buie, Lowell Observatory as quote.pro   ", "red_mysql_quote", " Convert a string into one safe for including in a mySQL query   Similar to the mysql function quote. Leading and trailing blanks are  removed. Leading and trailing quotes are preserved but are  considered to be delimiters for the string provided there is a  leading and a trailing quote. If there is just one it is considered  to be interior to the string. An interior single quote is converted  to \' and a backslash is converted to \\. Embedded newlines  (string(10B)) are quoted with '\n' where n is the letter n.   On output, the string will have leading and trailing quotes added if  they weren't already there. However, if the string is a scalar and  it is 'NULL' (4 characters) after stripping blanks it is returned as  is without quotes.   The input can either be a single string or a string array. If an  array, the strings are joined with a quoted newline separator. For  example, s = quote(['this text output','more of the output'])  produces   'this text output\nmore of the output'   as a scalar  string. This feature exists to support comment fields of type TEXT  or BLOB. In multiline cases (input is a string array or contains 10B  newline characters) empty or all whitespace lines at the begining or  end of the total string will be trimmed. A single such line comes  back as a ''.   Newlines are currently quoted with two characters: '\n' where the n  is a literal lower case n. It is inadvisable to try to use an actual  '\n' within the string to be quoted, although it will work currently  if the string is a scalar and contains no embedded 10B characters.   ", "LITERAL     if set, some of the processing of quote is not done,      specifically removal of trailing/leading blanks, special      treatment for the string 'NULL', and removal of leading and      null/whitepace lines in the multiline cases. The processing of      single quotes and backslashes in the input string is the same.   str      String(s) to be processed. If a string array, the strings are       joined with a newline quoted after each string including the       last. Embedded newline characters (10B) are also quoted in       this way.   ", "SST pipeline", "  2003-08-12 : MWB. First version    2006-10-27 : Peter L. Collins, Lowell Observatory. Add support for                string array input (with newlines)    2006-11-28 : PLC. Allow literal (string(10B)) newlines in str.    2006-12-11 : PLC. Disconnect LITERAL flag from rank of str and                (except if LITERAL) trim leading and trailing null or                all whitespace lines in the multiline cases.    2016-10-24 : MWB, added support for quoting a semi-colon      Return value is a string that is ready for mySQL.   ");
  
  

