  libdata[libdataItem++] = new Array("./red_mysql_select.html#red_mysql_select", "red_mysql_select", 'routine in <a href="./red_mysql_select.html">red_mysql_select.pro</a>', "red_mysql_select.pro", "", "red_mysql_select", " Submit MySQL SELECT query and get struct with results from a table.   Requires an open connection to MySQL server (established by use of  openmysql) as well as valid permissions for whatever query or  command is to be executed.   :Categories:      SST pipeline   :Author:      Mats Löfdahl, Institute for Solar Physics.   :Params:      lun : in, type=integer        The logical unit of the pipe (opened by openmysql).      table : in, type=string        The table in which the query is done.      variables : out        A list of variables to recieve columns of output. Default type       is ascii, but use the format keyword to specify other data       types.      query : in, type=strarr        Query line(s) to send to pipe. Do not include the  FROM table        part. Specify the table in its parameter.    :Keywords:      count : out, type=integer        Number of valid lines found that were read.      column_names : out, optional, type=strarr        Column names, all columns.      column_types : out, optional, type=strarr        Column types, all columns.      distinct : in, optional, type=boolean        Do SELECT DISTINCT, returning only distinct (unique) matches.      verbose : in, type=boolean        Flag turns on debugging output to standard out.   :History:     2018-06-28 : MGL. First version.     2018-07-02 : MGL. New keyword distinct.   ", "column_namescolumn_typescountdistinctselect_expressiontableverbosewhere_conditionlun", "          -1", "");
  
  

