  libdata[libdataItem++] = new Array("./red_neckel_coefficients.html#red_neckel_coefficients", "red_neckel_coefficients", 'routine in <a href="./red_neckel_coefficients.html">red_neckel_coefficients.pro</a>', "red_neckel_coefficients.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_neckel_coefficients", " Neckel's limb darkening coefficients for 300 nm &lt;= lambda &lt;  1100 nm.   ", "analytical        Get coefficients from Neckel (2005) instead of default Neckel         & Labs (1994).   lambda       The wavelength in units of meters.   ", "SST pipeline", "    2021-09-06 : MGL. First version, based on private IDL library                  function neckel_coefficients().    ");
  
  

