  libdata[libdataItem++] = new Array("./red_nnumber.html#red_Nnumber", "red_Nnumber", 'routine in <a href="./red_nnumber.html">red_nnumber.pro</a>', "red_nnumber.pro", "", "red_Nnumber", " NAME:        NNUMBER  PURPOSE:        Convert an integer to a string with leading 0s  CATEGORY:        Type conversion  CALLING SEQUENCE:        RESULT = NNUMBER ( INT, DIGITS )  INPUTS:        INT     : Value for string, converted to integer.        DIGITS  : Number of max. digits for the string  OUTPUTS:        String of length DIGITS with leading zeroes  MODIFICATION HISTORY:        15-Dec-1992  P.Suetterlin, KIS  ", "valuendigits", "          -1", "");
  
  

