  libdata[libdataItem++] = new Array("./red_noiselevel.html#red_noiselevel", "red_noiselevel", 'routine in <a href="./red_noiselevel.html">red_noiselevel.pro</a>', "red_noiselevel.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_noiselevel", " Measure the standard deviation of white noise in an image.   Measures the level of the power spectrum of pic, in the area where  there should be no signal and no dreadful cross.   ", "OversamplingRate     The oversampling factor, limfreq/Nyquist.   LimFreq     The diffraction limit in pixels.   Fourier     Pic is the Fourier transform of an image.   Pic     The image in which to measure the noise level. If Pic is 2D,      then return a scalar. If Pic is 3D, assume array has dimensions      [sz,sz,Nim] and return array with Nim noise levels.   ", "SST pipeline", "   1993-09-02 : MGL. First version (in ANA)     2019-05-22 : MGL. Incorporated in SSTRED.      Noise stddev in counts.   ");
  
  

