libdata[libdataItem++] = new Array("./red_paramstostruct.html", "red_paramstostruct.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_paramstostruct.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_paramstostruct.html#red_paramstostruct", "red_paramstostruct", 'routine in <a href="./red_paramstostruct.html">red_paramstostruct.pro</a>', "red_paramstostruct.pro", "   Ed Shaya / U. of Maryland [April 27, 2012] (as paramtostruct)   ", "red_paramstostruct", "   Converts a parameter string array (eg, header for FITS files) into    an IDL structure where each keyword is a tag of a structure and    each of these structures contain a value and a comment. The values    should by datatyped (float, int, string, etc) correctly. Logical T    is transformed to 1byte and F to 0byte. Does not work on PDS    labels because it requires unique keynames and OBJECT and    END_OBJECT can be repeated.   ", "commentChar      Character that begins the comment on each line.   inverse      Set this to convert from the struct form to a string array       suitable for making a FITS header.   input      A string consisting of 'key = value'. Value can have spaces.       Comments (which describe the keyvalue) are on the same line and       after the value and start with the commentChar character. (eg,       ' keyword = 17.3 / A keyword with floating point value')   ", "Datafile handling", "     2016-05-18 : MGL. Change documentation header format. Add                   keyword inverse, this will make a string array out                   of a struct. Change input variable name to input.                   Check if commentChar is given with n_elements, not                   keyword_set.       A structure in which each keyword is a tag holding a structure.     Each of these structure hold a value and a comment.   ");
  
  

libdata[libdataItem++] = new Array("./red_parseparameter.html", "red_parseparameter.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_parseparameter.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_parseparameter.html#red_parseparameter", "red_parseparameter", 'routine in <a href="./red_parseparameter.html">red_parseparameter.pro</a>', "red_parseparameter.pro", "   Ed Shaya / U. of Maryland [April 27, 2012] (as parse_parameter)   ", "red_parseparameter", "   Parse a string containing 'key = value' pairs, optionally with a    comment.     Given a string from a parameter/header ('key = value'), returns key and    value of a parameter as two element array by basically splitting on an    equal sign. If commentChar is set to the delimiter for start of a    comment, then it returns a 3 element array [key, value, comment].    Keyword  pos  returns position of beginning of key.    If there is no equal sign, then it returns [strtrim(line,2),''] and    pos = -1.   ", "pos      Position of first character of key in paramArr   commentChar      Character that begins a comment or description   line      A string consisting of 'key = value'.  Value can have spaces.   ", "Datafile handling", "     2016-05-18 : MGL. Change documentation header format.       Two-element array with [key,value] as strings. Or, if commentChar     keyword is set, three-element array with [key,value,comment]   ");
  
  

