libdata[libdataItem++] = new Array("./red_planefit.html", "red_planefit.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_planefit.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_planefit.html#red_PLANEFIT", "red_PLANEFIT", 'routine in <a href="./red_planefit.html">red_planefit.pro</a>', "red_planefit.pro", "", "red_PLANEFIT", " NAME: 	PLANEFIT  PURPOSE: 	Least-squares fit of a plane to a set of (X,Y,Z) points: 		Z=R(0)+R(1)*X+R(2)*Y  CALLING SEQUENCE: 	coef = PLANEFIT( x,y,z,0., yfit )  ; for equal weighting 	coef = PLANEFIT( x,y,z, weights_vector, yfit ) ;otherwise  INPUT: 	XIN, YIN, ZIN = the points to be fit 	Weights_vector = their weights. (For equal weights, let W=0.)  RETURNS: 	coef = the fit coefficients  OPTIONAL OUTPUT: 	YFIT = the Z values at (X,Y), calculated from the fit   NOTE: 	If a fit is not possible, R will be returned as a scalar, the average 	of Z.  REVISION HISTORY: 	Written by H.T. Freudenreich, HSTX, 5/18/93  ", "XINYINZINWYFIT", "          -1", "");
  
  

