  libdata[libdataItem++] = new Array("./red_progressbar.html#red_progressbar", "red_progressbar", 'routine in <a href="./red_progressbar.html">red_progressbar.pro</a>', "red_progressbar.pro", "    Mats Löfdahl, ISP   ", "red_progressbar", " Display progress in teminal window.   ", "barlength       The length of the status bar in number of characters.   nobar       If set, do not show a status bar.   predict       Print a prediction for the remaining time.   i       The progress so far.   N       Normalize i with this number.   message       A message identifying the task for which progress is being        made.   ", "CRISP pipeline", "     2016-05-25 : MGL. First version, code taken from                   red_sumfiles.pro.       2016-10-10 : MGL. Implemented a real bar.       2016-10-25 : MGL. Deal with N=0 and N=1.       2016-10-28 : MGL. Don't need to send the message when finishing.       2016-10-31 : MGL. Remove keyword finished, just test i vs. N for                   completion. Make message a parameter instead of a                   keyword. New keyword clock.       2016-11-16 : MGL. New keyword predict.       2016-11-28 : MGL. Call red_timestring with /interval.       2017-05-08 : MGL. Try to make predictions more robust. Adapt                   output line to teminal width.       2017-10-24 : MGL. Replace keyword clock with a common block.       2018-01-22 : MGL. Allow not calling red_progressbar for every                   iteration.   ");
  
  

libdata[libdataItem++] = new Array("./red_quicklook_batch.html", "red_quicklook_batch.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_quicklook_batch.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_quicklook_batch.html#red_quicklook_batch", "red_quicklook_batch", 'routine in <a href="./red_quicklook_batch.html">red_quicklook_batch.pro</a>', "red_quicklook_batch.pro", "    Oleksii Andriienko, ISP   ", "red_quicklook_batch", " Create quicklooks for a range of dates.   ", "work_dir       Base directory where directories for quicklooks were created.   data_dir       Root directory for data (default: '/data')   instruments       Instruments' names to be used for quicklook movies.   choose_states        Set this keyword to choose spectral points to be used for         quicklook movies. If not set then 'core_and_wings'         keyword will be used in a call of         red__quicklook.pro. Preferably use 'choose_states'         if you are sure that same spectral sequences were         used for the whole range of observational dates.   overwrite       Overwrite existing quicklooks.   min_nscan       Minimal number of scans in a data set.   no_db       Set this keyword to prevent using database to get metadata.   nthreads       Number of threads.   do_wb       Set this keyword to generate wb quicklook movies.   dates       Dates in format YYYY-MM-DD:MM-DD or YYYY-MM-DD   ", "SST pipeline", "     2020-06-20 : OA. First version.       2022-03-25 : OA. Added calls to red__setupworkdir. Added                   data_dir, choose_states, do_wb and no_db keywords.   ");
  
  

