  libdata[libdataItem++] = new Array("./red_readhead_momfbd.html#red_readhead_momfbd", "red_readhead_momfbd", 'routine in <a href="./red_readhead_momfbd.html">red_readhead_momfbd.pro</a>', "red_readhead_momfbd.pro", "    Mats Löfdahl, ISP   ", "red_readhead_momfbd", " Return a fits-type header from a MOMFBD format file.   ", "version       The version of the momfbd (or redux) program that wrote the        file.   fname       The name of the data file.   ", "SST pipeline", "    2017-03-10 : MGL. Moved reading of headers from MOMFBD format                  files from red_readhead.pro.      2017-03-17 : MGL. New keyword  version .      2017-11-10 : MGL. Use the new roi field in the struct returned by                  momfbd_read to get predictable dimensions that match                  the output of red_readdata.      2017-11-12 : MGL. Update dimensions to match new convention in                  struct returned by momfbd_read.    ");
  
  

