libdata[libdataItem++] = new Array("./red_remap_image.html", "red_remap_image.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_remap_image.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_remap_image.html#Red_remap_image", "Red_remap_image", 'routine in <a href="./red_remap_image.html">red_remap_image.pro</a>', "red_remap_image.pro", "", "Red_remap_image", " NAME:        RED_REMAP_IMAGE  PURPOSE:        Do a 1:1 alignment of two images using warping techniques  CALLING SEQUENCE:        Res = Map_Image( Ref, Image, Cell [, Step ] [, /ALIGN]  INPUTS:        Ref:    Reference image        Image:  Original image        Cell:   (integer)  OPTIONAL PARAMETERS:        Step:   (int) Stepwidth of the correlation grid.  If omitted,                same value as Cell is used  KEYWORDS:        ALIGN   (Flag) If set, an allover crosscorrelation of the                images will be performed to remove a full-frame shift.         MAP:    name of a variable to pass back the distortion map.         PLOT:   (float) Display image and shift vectors, latter scaled                by a factor of PLOT         RANGE:  (integer) Allowed range for displacements.                Correlations will only be looked for in +/-RANGE.                The parameter is just passed to shc.        REFINE_SHIFTS: (flag) If the computed shift is larger than RLIM then                recompute it with the properly centered subimage        RLIM:   (integer) Limit when to recompute shifts (DEFAULT: 1)        RCS:    (integer) Cell size for shift refinement. (DEFAULT: cell)        SAME_SCREEN: (flag) Use the currently active window for                plotting.  Default is to open a new one.        SMOOTH: (integer) Smooth images with a boxcar of width SMOOTH                before computing the displacement map.  OUTPUTS:        Res:    Warped image of same type as input image, size is the                min of the sizes of the two images.  RESTRICTIONS:   PROCEDURE:        Divide the two images into subfields of cellsize Cell, using        stepwidth Step.  Compute the shifts between the subimages and        set-up a polynomial warping matrix.  Call WARP_TRI to do the        warping.  MODIFICATION HISTORY:        10-Jun-1997  P.Suetterlin, USG        11-Sep-2001  call empty after plot to assure all arrows are there        05-Feb-2002  Rename to remap_image - there's already a                     map_image in the standard IDL.        04-Mar-2002  Smoothing of images before calculation of shifts        13-Jan-2014  Option to refine (large) shifts        15-Jan-2014  include in crispred as red_remap_image        16-Apr-2014  Change /edge to /edge_truncate in call to smooth                     becasue in IDL v.8 there are two new keywords                     that start with  edge .  ", "ALIGNMAPPLOTQUINTRANGESAME_SCREENSMOOTHMEDIANDONT_FIX_BORDERREFINE_SHIFTSrlimRCSrefpiccssw", "          -1", "");
  
  

