libdata[libdataItem++] = new Array("./red_rot_magn_align.html", "red_rot_magn_align.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_rot_magn_align.pro", "", "", " Find rotation, magnification, and alignment parameters that align  one image to another.  ", "", "          -1", "");
  
  
