  libdata[libdataItem++] = new Array("./red_select_subset.html#red_select_subset", "red_select_subset", 'routine in <a href="./red_select_subset.html">red_select_subset.pro</a>', "red_select_subset.pro", "    Mats Löfdahl, 2013-10-03   ", "red_select_subset", " Select subset from a list.   ", "count defaulthelp      Set this to get instructions.   indxmaxcount      The maximum number of elements in the output.   qstringlist      This is the list to chose from,   ", "SST observations", "     2013-10-03 : MGL. Use red_expandrange instead of expandrange.       2013-12-05 : MGL. A single dash will select nothing. New keyword                   indx for the selected indices.       2016-09-26 : MGL. If none selected, undefine indx.       2016-10-05 : MGL. Allow non-string defaults.       2018-09-17 : MGL. New keyword maxcount.       The list of selected elements.   ");
  
  

