  libdata[libdataItem++] = new Array("./red_show.html#red_show", "red_show", 'routine in <a href="./red_show.html">red_show.pro</a>', "red_show.pro", "", "red_show", " Image displaying routine.    :Categories:      CRISP pipeline    :Author:      Jaime de la Cruz Rodriguez 2008   :Params:       vari : in, type= array or string           A 2D image (possibly with color, making the array 3D) or the         name of a file with such content.   :Keywords:       log : in, out, optional, type=float          Display in log scale with specified added number. More         specifically, display log(abs(vari + log*max(var))).       wnum : in, out, optional, type=integer          Integer window index       nowin : in, optional, type=boolean           Set this to not recreate the window       offs : in, type=integer, default=57          Integer removes pixel from the Y-dimension of         the screen so compensates for the menubar and so on.       opt : in, optional, type=boolean          Do a histogram optimization on the intensity limits.        reuse : in, optional, type=boolean          Re-use existing window, if there is one with the appropriate         wnum.       scroll : in, optional, type=boolean          Make window with scrollbars for large images instead of         shrinking.       title : in, optional, type=string          If a window is created, it will have this title.    :History:      2013-07-24 : Renamed red_show for inclusion in crispred pipeline.      2013-09-20 : MGL. Added title keyword.      2019-10-17 : MGL. New keyword reuse.      2020-04-07 : MGL. New keyword scroll.      2024-07-06 : MGL. Allow file name as input parameter.      2025-11-18 : MGL. New keyword log.   ", "lognoscalenowinoffsoptreusescrolltitlewnumvari", "          -1", "");
  
  

