  libdata[libdataItem++] = new Array("./red_solarsoft_get_sun.html#red_solarsoft_get_sun", "red_solarsoft_get_sun", 'routine in <a href="./red_solarsoft_get_sun.html">red_solarsoft_get_sun.pro</a>', "red_solarsoft_get_sun.pro", "", "red_solarsoft_get_sun", " NAME:        GET_SUN  PURPOSE: 	Provides geocentric physical ephemeris of the sun.        Front end to routine SUN to provide 'Yohkoh-style' time interface  CATEGORY:   CALLING SEQUENCE:        OUT = GET_SUN(ITEM)  INPUTS:        ISODATE - Reference time for ephemeris data.  Interpreted as 	  an ephemeris time (ET).  The difference between ephemeris 	  time and universal time (Delta T = ET - UT) is not 	  completely predictable but is about 1 minute now.  This 	  difference is noticable slightly.  Should be given in ISO 	  form, yyyy-mm-dd.  KEYWORD INPUTS:       /LIST :	Displays values on screen.  OUTPUTS: 	DATA = Vector of solar ephemeris data: 	  DATA( 0) = Distance (AU). 	  DATA( 1) = Semidiameter of disk (sec). 	  DATA( 2) = True longitude (deg). 	  DATA( 3) = True latitude (0 always). 	  DATA( 4) = Apparent longitude (deg). 	  DATA( 5) = Apparent latitude (0 always). 	  DATA( 6) = True RA (hours). 	  DATA( 7) = True Dec (deg). 	  DATA( 8) = Apparent RA (hours). 	  DATA( 9) = Apparent Dec (deg). 	  DATA(10) = Longitude at center of disk (deg). 	  DATA(11) = Latitude at center of disk (deg). 	  DATA(12) = Position angle of rotation axis (deg). 	  DATA(13) = decimal carrington rotation number.  KEYWORD OUTPUTS 	DIST 		= Distance in AU. 	SD 		= Semidiameter of disk in arc seconds. 	TRUE_LONG	= True longitude (deg). 	TRUE_LAT 	= 0 always. 	APP_LONG 	= Apparent longitude (deg). 	APP_LAT 	= 0 always. 	TRUE_RA 	= True RA (hours). 	TRUE_DEC 	= True Dec (deg). 	APP_RA 		= Apparent RA (hours). 	APP_DEC 	= Apparent Dec (deg). 	HE_LON 		= Longitude at center of disk (deg). 	HE_LAT 		= Latitude at center of disk (deg). 	PA 		= Position angle of rotation axis (deg). 	CARR		= decimal carrington rotation number.  COMMON BLOCKS:  NOTES:        Notes: based on the book Astronomical Formulae          for Calculators, by Jean Meeus.          If no arguments given will prompt and list values.  MODIFICATION HISTORY: 	Feb, 1994 - GLS - Written to provide 'Yohkoh style' time 	  interface to routine SUN.PRO by R. Sterner, 19 Feb, 1991        8-Oct-1998 - S.L.Freeland - allow any SSW time (via anytim                     front end)        2021-12-15 - MGL. Adapt for use in SSTRED, without any other                     solarsoft dependencies.   Copyright (C) 1991, Johns Hopkins University/Applied Physics Laboratory  This software may be used, copied, or redistributed as long as it is not  sold and this copyright notice is reproduced on each copy made.  This  routine is provided as is without any express or implied warranties  whatsoever.  Other limitations apply as described in the file disclaimer.txt.  ", "etlondisttrue_longapp_longtrue_latapp_latsdtrue_raapp_ratrue_decapp_decpahe_lonhe_latcarrlistqsisodate", "          -1", "");
  
  

