libdata[libdataItem++] = new Array("./red_time2double.html", "red_time2double.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_time2double.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_time2double.html#red_time2double", "red_time2double", 'routine in <a href="./red_time2double.html">red_time2double.pro</a>', "red_time2double.pro", " ", "red_time2double", " Convert a time string to the number of seconds after midnight (or  the reverse operation).   ", "dir       Set this to do the reverse operation, make a string.   inverse       Set this to do the reverse operation, make a string.   t       Scalar or array representing time, either as a string or (if        the dir keyword is set) the number of seconds after midnight.        In the string case, the following format is assumed:        hh[:mm[:ss[.ddd]]].   ", "CRISP pipeline", "   2013-06-04 : Split from monolithic version of crispred.pro.     2013-08-16 : MGL. Added documentation.     2013-11-11 : MGL. In the string making part, fraction of seconds                 was added to number of seconds already including the                 fraction. Fixed this.     2014-04-30 : MGL. Input data t can now be an array. Also, be more                 relaxed about t's format.     2014-05-31 : MGL. New inverse keyword, does the same as dir                 keyword.     2016-10-20 : JLF. Fix short int bug.       The number of seconds after midnight or (if the dir keyword is     set) the time as a string.   ");
  
  

libdata[libdataItem++] = new Array("./red_time2string.html", "red_time2string.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_time2string.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_time2string.html#red_time2string", "red_time2string", 'routine in <a href="./red_time2string.html">red_time2string.pro</a>', "red_time2string.pro", "", "red_time2string", " PURPOSE:   This function converts a time length in seconds to a more readible   string version of that number in years, days, minutes, and seconds   CATEGORY:   utilities   CALLING SEQUENCE:   result = red_time2string(time, [/days])   INPUTS:   time: A time length in seconds   KEYWORD PARAMETERS:   days: If set, time is interpreted to be a length in days, not seconds.   OUTPUTS:   That time, converted to a more sensible string   EXAMPLE:   IDL> print, red_time2string(3605.5)     1 hour,  0 minutes and  5.5 seconds   IDL> print, red_time2string(!dpi * 1D8)     9 years, 351 days,  2 hours, 27 minutes and 45.4 seconds   IDL> print, red_time2string(1.5, /days)     1 day, 12 hours,  0 minutes and 0.0 seconds   MODIFICATION HISTORY:   April 5 2009: Written by Chris Beaumont   April 7 2009: Added \days keyword   December 15 2025: MGL. Add red_ namespace for inclusion in sstred.  ", "daystime", "          -1", "");
  
  

libdata[libdataItem++] = new Array("./red_time_conv.html", "red_time_conv.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_time_conv.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_time_conv.html#red_Time_conv", "red_Time_conv", 'routine in <a href="./red_time_conv.html">red_time_conv.pro</a>', "red_time_conv.pro", "", "red_Time_conv", " NAME: 	red_Time_conv  PURPOSE: 	Onvert a Time string HH:MM:SS to seconds or vice versa  CALLING SEQUENCE: 	Res = red_Time_conv( Time )  INPUTS: 	Time : Either integer value with number of seconds or string               with time of the day in format HH:MM:SS  KEYWORDS:        F2S  : Default is convert string to integer, F2S reverts.        FRAC : (integer) if specified and non-zero, write fractions of               seconds with FRAC digits  OUTPUTS:  	Res : integer with number of seconds or string in format              HH:MM:SS, depending on Keyword F2S  MODIFICATION HISTORY: 	01-Apr-1991  P.Suetterlin, KIS        17-Dec-2010  PS output fractional seconds        25-Dec-2010  PS fix zero padding in fraction        2013-07-12 : MGL. Renamed to red_time_conv for inclusion in                     crispred pipeline.   ", "f2sfracintime", "          -1", "");
  
  

libdata[libdataItem++] = new Array("./red_timeplot.html", "red_timeplot.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_timeplot.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_timeplot.html#red_timeplot", "red_timeplot", 'routine in <a href="./red_timeplot.html">red_timeplot.pro</a>', "red_timeplot.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_timeplot", " Plot data with vs time with a proper axis.   ", "overplot       Set this keyword if you wish to overplot data on an already        exisiting set of axes. It is like calling the IDL OPLOT        command.   trange       As xrange.   xrange       See the regular plot command.   _extrat       The time coordinate in seconds after midnight.   y       The dependent coordinate.   ", "SST pipeline", "   2020-01-14 : MGL. First version.    ");
  
  

libdata[libdataItem++] = new Array("./red_timestamp.html", "red_timestamp.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_timestamp.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_timestamp.html#red_timestamp", "red_timestamp", 'routine in <a href="./red_timestamp.html">red_timestamp.pro</a>', "red_timestamp.pro", "    Mats Löfdahl, Institute for Solar Physics      Parts stolen from The Coyote Graphics timestamp command, see     http://www.idlcoyote.com/.   ", "red_timestamp", " Make a time stamp for the current time.   ", "utc         If this keyword is set, the UTC time will be used for          the time stamp instead of the local time.   iso         If this keyword is set, the timestamp will be formatted as          YYYY-MM-DDThh:mm:ss.   ", "CRISP pipeline", "   2013-09-02 : MGL. First version.     2016-05-30 : MGL. New keyword  iso .       A timestamp string formatted like: YYYYMMDD@hh:mm:ss.   ");
  
  

libdata[libdataItem++] = new Array("./red_timestring.html", "red_timestring.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_timestring.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_timestring.html#red_timestring", "red_timestring", 'routine in <a href="./red_timestring.html">red_timestring.pro</a>', "red_timestring.pro", "    Mats Löfdahl   ", "red_timestring", " Make a string representation of time in seconds since midnight.   ", "Nsecdecimals        Use this number of decimals for the seconds.   shortinterval        Set this keyword to interpret t as a time interval, producing         a different type of string.   t ", "CRISP pipeline", "     2016-09-22 : MGL. First version, based on red_time2double.                   Specify number of decimals by using keyword. Allow                   to wrap to day(s) before (negative numbers) or                   day(s) after (large numbers).       2016-11-16 : MGL. New keyword short.       2016-11-28 : MGL. New keyword interval.       A string on the form hh:mm:ss.[ddd...], where   ");
  
  

libdata[libdataItem++] = new Array("./red_turret_select_pointing.html", "red_turret_select_pointing.pro", '.pro file in <a href="./dir-overview.html">./ directory</a>', "red_turret_select_pointing.pro", "", "", "", "", "          -1", "");
  
  
  libdata[libdataItem++] = new Array("./red_turret_select_pointing.html#red_turret_select_pointing", "red_turret_select_pointing", 'routine in <a href="./red_turret_select_pointing.html">red_turret_select_pointing.pro</a>', "red_turret_select_pointing.pro", "    Mats Löfdahl, Institute for Solar Physics   ", "red_turret_select_pointing", " ", "time      This is an array of time coordinates in s after midnight. If       given as input, the returned pointing coordinates will be       interpolated to those points in time. If not, it is simply       returned as the time coordinate in turretdata.   turretdata      A struct array with info from the turret logfile. The turret       program stores pointing information of different types       depending on what it's doing, these types are tagged in       different ways.   pointingtype      The pointing type tag to select, one of  Stonyhurst ,  Disk ,        Flat , or  Pointing . If  Pointing , information from the       former three types are combined and returned as cartesian disk       coordinates.   isodate      The date in ISO format. (Needed only if we need to convert       Stonyhurst coordinates from old turret logfiles.)   ", "SST pipeline", "    2017-04-23 : MGL. First version.      2021-12-16 : MGL. Implemented combined pointingtype  Pointing .       An array with pointing coordinates.   ");
  
  

