  libdata[libdataItem++] = new Array("./red_writedata.html#red_writedata", "red_writedata", 'routine in <a href="./red_writedata.html">red_writedata.pro</a>', "red_writedata.pro", "     Tomas Hillberg, ISP, 2016-05-26   ", "red_writedata", " Camera-independent write routine.   ", "header filetype        The type of file to write. Allowed values are:          ana  or  fits          If not set auto-detection will be attempted.   structheader        If set, convert the header from struct to strarr         before writing.   status        Output the return status, 0 for success, -1 for failure.   overwritecompresstabhdu	 struct containing the header keywords expressed as binary 	 table vectors. 	 tabhdu.[extnames] = 1 extension per substruct (named [extname]) 	 tabhdu.[extnames].comment = comment for the extname keyword 	 tabhdu.[extnames].[tabkeys] = 1 tabluated keyword per sub-substruct 					(named [tabkey], also used for ttypen) 	 tabhdu.[extnames].[tabkeys].{val,comment,summary}: 			val = the array to be written to the table 			comment = main hdr comment and ttypen comment 			summary = value to put in main hdr for this keyword 	 sub-structure keys that don't exist are replaced with defaults, blank 	 for comment, mean(val) for summary   filename       The file name.   data", "CRISP pipeline", "   2016-05-26 : THI. First version     2016-09-16 : JLF. Added tabhdu, binary table writing. Also fixed a                 /overwrite bug (it'd overwrite even if you didn't use                 /overwrite)     2016-12-07 : MGL. Split binary table helper procedures into                 separate files.    ");
  
  

